      t += v[A + i * C];
    }
    bool f = true;
    for (int i = 1; i <= K; i++) {
      t += v[i * C];
      if (s.count(i * C)) {
        f = false;
        break;
      }
    }
    if (f) res = max(res, t);
  }
  return res;
}

