set<ll> SET;

int main(){

	scanf("%lld",&N);
	for(ll i = 0; i < N; i++){

		scanf("%lld",&S[i]);
	}

	ll ans = 0;
	ll L,R;

	for(ll diff = 1; diff <= N-2; diff++){

		ll tmp = 0;
		SET.clear();

		L = 0,R = N-1;
		SET.insert(L);
		SET.insert(R);

		bool FLG = true;

		while(true){

			L += diff;
			R -= diff;
			if(R < 0)break; //奇数回目動の方が1回多いはず

			if(L <= N-1 && SET.count(L)){
				FLG = false;
				break;
			}
			if(SET.count(R)){
				FLG = false;
				break;
			}
			if(L <= N-1){
				SET.insert(L);
				tmp += S[L];
			}
			SET.insert(R);
			tmp += S[R];
		}

		if(FLG){

			ans = max(ans,tmp);
		}
	}

	printf("%lld\n",ans);

	return 0;
}

