vector<ll> factorize(ll x) {
    vector<ll> res;
    for (ll i = 1; i * i <= x; ++i) {
        if (x % i) continue;
        res.push_back(i);
        if (i * i != x) res.push_back(x / i);
    }
    return res;
}

