signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;
	vector<int> s(n);
	for (auto &t : s) {
		cin >> t;
	}
	if (n > 10000) {
		cout << "sosi" << endl;
		return 0;
	}
	int ans = 0;
	auto rlx = [&](int a, int b, int k) {
		int c = a - b;
		if (a % c == 0 && c / a <= k) return;
		int cp = 0;
		int cr = 0;
		int ok = 1;
		vector<int> us(n + 1);
		us[0] = 1;
		for (int i = 0;; i++) {
			if (i & 1) {
				// assert(cp >= b);
				if (cp < b) {
					ok = 0;
					break;
				}
				cr += s[cp - b];
				cp -= b;
				// assert(!us[cp]);
				ok &= (!us[cp]);
				us[cp] = 1;
			} else {
				// assert(cp + a <= n);
				if (cp + 1 > n) {
					ok = 0;
					break;
				}
				cr += s[cp + a];
				cp += a;
				// assert(!us[cp]);
				ok &= (!us[cp]);
				us[cp] = 1;
			}
			if (cp == n) break;
		}
		if (ok) ans = max(ans, cr);
	};
	// rlx(4, 3, 4);
	n--;
	for (int k = 0; k <= n; k++) {
		for (int c = 0; c <= n; c++) {
			int a = n - k * c;
			int b = a - c;
			if (a > 0 && b >= 0 && a > b && a < n) {
				rlx(a, b, k); 
			}
		}
	}
	cout << ans << endl;
}

