ll solve() {
    ll ans = 0;
    for (int d = 1; d < N - 1; d++) {
        for (int k = 0; k * d < N - 1; k++) {
            int a = N - 1 - k * d;
            ll t = 0;
            ll ok = true;
            for (int i = 0; i <= k; i++) {
                if (used[i * d]) {
                    ok = false;
                }
                used[i * d] = true;
                t += s[i * d];
                if (used[i * d + a]) {
                    ok = false;
                }
                used[i * d + a] = true;
                t += s[i * d + a];
            }
            if (ok) {
                ans = max(ans, t);
            }
            for (int i = 0; i <= k; i++) {
                used[i * d] = false;
                used[i * d + a] = false;
            }
        }
    }

    return ans;
}

