void solve(long long N, vector<long long> s){
  long long k, x;
  long long a, b;
  long long ans = 0;
  for (long long c = 1; c <= N-2; c++) {
    k = 1;
    x = 0;
    map<int, int> used;
    while (k*c < N-1) {
      a = N-1-k*c;
      b = a - c;
      if (a < 1 || b >= a || b < 1 || used.find(k*c)!=used.end() || used.find(N-1-k*c)!=used.end() || k*c == N-1-k*c) {
        break;
      }
      x += s[k*c];
      x += s[N-1-k*c];
      used[k*c] = 1;
      used[N-1-k*c] = 1;
      ans = max(ans, x);
      k++;
    }
  }
  std::cout << ans << std::endl;
}

