// 代价 2*\sum R[i] - max{R[i]}。枚举走到最远点时的衣服的颜色。
// f[i]：最远走到位置i的情况下的最优解。
// N类物品，第i类物品有C[i]件，第j件的花费为cost[i][j]，价值为val[i][j]。同一类商品，花费与价值正相关。
// 每类物品最多买一件。求总价值不小于K的的情况下的最小花费。
// f[i][j]，在位置i之前（不包括位置i），观察除了颜色j之外的狗，至少 K - sum[j] 只，至少要走多长的路程（只算单程）？
// (dis, sum)
// (dis1 + dis2, sum1 + sum2)
//
//
// ABC128F https://atcoder.jp/contests/abc128/tasks/abc128_f
// 一开始我理解错题意了。我以为每一步可以选择操作2或者操作3。实际上按照题目描述，并不是操作2，操作3；而是step 2，step 3。
// 也就是说青蛙的位置依次是 0, A, A-B, (A-B)+A, 2(A-B), 2(A-B)+A, ..., k (A - B), k(A-B)+A = n - 1
// 因此我们只要枚举 (A-B) and iterate over k

int n; scan(n);
vi s(n); scan(s);
ll ans = 0;
// 1 <= B < A < n - 1
// 1 <= A - B <= n - 3
up (d, 1, n - 3) {
    ll sum1 = 0, sum2 = 0;
    for (int a = n - 1 - d, r = d; a > d; a -= d, r += d) {
        // 实际上就是两个（由数组s的下标构成的）等差数列。
        //一个从左往右，首项是0，公差是d；另一个从右往左，首项是n-1，公差是-d。
        if (a <= r && a % d == 0) break; // 判断往右经过的点和往左经过的点是否有重合
        sum1 += s[r];
        sum2 += s[a];
        Max(ans, sum1 + sum2);
    }
}
