template<class Type>
Type solve(Type res = Type()){
    ll N; cin >> N;
    vector<ll> s(N); for(auto& in:s) cin >> in;

    for(int C = 1; C < N;C++){
        map<ll,int> mp;
        ll dp = 0;
        for(int k = 1; k < N; k++){
            if((k+1)*C >= N-1) break;
            ll p1 = N-1-k*C;
            ll p2 = k*C;
            if(mp[p1]) break;
            mp[p1]++;
            if(mp[p2]) break;
            mp[p2]++;

            dp += s[N-1-k*C] + s[k*C];
            res = max(res,dp);
        }
    }
    return res;
}
