        for (int k = 1; k * C < N; ++k) {
            if ((N - 1) % C == 0 && (N - 1) / C >= k) {
                break;
            }

            sum_prev += S[k * C] + S[N - 1 - k * C];

            ans = max(ans, sum_prev);
        }
    }

    write(ans);
