		long long int tmp = 0; // S[0] + S[N-1] から始めて次は S[m] + S[N-1-m] を足す感じ
		for(int j = 1; j * m < N - 1; j++){
			if((N - 1) % m == 0 && N - 1 - j * m <= j * m) break; 
			tmp += S[j * m] + S[N - 1 - j * m]; 
			mx = max(mx, tmp); 
		}
		ans = max(ans, mx); 
	}
	cout << ans << endl; 
}

