void init()
{
    for(ll i=1;i<n;i++)
    {
        ll pre=0;
        for(ll j=i;j<n;j+=i)
        {
            pre+=s[j];
            divs[j].push_back(i);
            scores[i].insert(make_pair(j,pre));
        }
        sum[i]=pre;
    }
}
bool fall(ll mov,ll A,ll land)
{
    ll g=__gcd(mov,A);

    ll firstmeet=A*mov/g;

    if(firstmeet<=land)
    {
        return true;
    }
    return false;
}
ll score(ll mov,ll A,ll land)
{
    if(A<=land)
    {
        auto it=scores[mov].lower_bound(make_pair(n-1-mov,0));
        return it->second;
    }
    else
    {
        ll det=0;
        auto it1=scores[mov].lower_bound(make_pair(A,0));
        if(it1->first!=A)
        {
            det=s[A];
        }
        it1--;

        auto it2=scores[mov].lower_bound(make_pair(land,0));

        return (sum[mov]-it1->second)+det+it2->second;

    }

}
ll calc(ll A,ll land)
{
    ll ret=0;
    for(ll i=0;i<divs[land].size();i++)
    {
        ll mov=divs[land][i];
        if(fall(mov,A,land))
        {
            continue;
        }
        ret=max(ret,score(mov,A,land));
    }
    return ret;
}
