int solve(int _count){

    int n = 0;
    input(n);
    vector<int> v(n);
    input(v);

    if(!static_cast<bool>(cin))
        return MOD;
#ifdef TEST
    cout << "Case: " << _count << endl;
#endif

    i64 ans = -INF;
    for(int d = 1; d <= n - 1; ++d){
        int k = (n - 1) % d;
        int a = k;
        unordered_set<int> p, q, w;
        i64 sum = 0;
        for(int t = a; t != n - 1; t += d){
            p.emplace(t);
            sum += v[t];
        }
        for(int t = d; t != n - 1 - a; t += d){
            q.emplace(t);
            sum += v[t];
            if(p.find(t) != p.end())
                w.emplace(t);
        }
        for(int m = 1; n - 1 - m * d >= 0; ++m){
            if(p.find(a) != p.end()){
                p.erase(a);
                sum -= v[a];
                if(w.find(a) != w.end())
                    w.erase(a);
            }
            if(q.find(n - 1 - a) != q.end()){
                sum -= v[n - 1 - a];
                q.erase(n - 1 - a);
                if(w.find(n - 1 - a) != w.end())
                    w.erase(n - 1 - a);
            }
            a += d;
            if(w.empty())
                chmax(ans, sum);
        }
    }

    cout << ans << endl;

    return 0;
}


