int main() {
	cin >> N;
	for (int i = 0; i < N; i++) {
		cin >> s[i];
	}

	ll ans = 0;// == 0の時の答えが0

	for (int C = 1; C <= N - 2; C++) {
		used.clear();
		//kを決めてる
		dp[0] = 0;
		for (int k = 1;; k++) {
			if (N - 1 - C * k <= 0)break;
