            if((N - 1 - k*C) % C != 0 || (N - 1 - k*C) / C > k) {
                if(score[k - 1][C] == -INF) continue;
                score[k][C] = score[k - 1][C] + s[N - 1 - k * C] + s[k * C];
                res = max(res, score[k][C]);
            } else {
                score[k][C] = -INF;
            }
        }
    }
    cout << res << endl;
}

