void solve(void)
{
	int n;
	cin >> n;
	vector<long> ss(n);
	for (long& v : ss) cin >> v;
	long ans = 0;
	for (int d = 1; d < n / 2; d++)
	{
		long res = 0;
		vector<int> vst(n);
		int l = 0, r = n - 1;
		while (l < r)
		{
			res += ss[l];
			res += ss[r];
			l += d;
			r -= d;
			if (vst[l] || vst[r])
			{
				break;
			}
			vst[l] = vst[r] = 1;
		}
		ans = max(ans, res);
	}
	cout << ans << endl;
}

