ll getans(int N, int A, int B) {
	if (B <= 0 || B >= A) return -1;
	nchk++;
	ll s = 0;
	int p = 0;
	while (1) {
		p += A;
		if (p == N - 1) break;
		chk[p] = nchk;
		s += in[p];
		p -= B;
		s += in[p];
		if (chk[p] == nchk) return -1;
		chk[p] = nchk;
	}
	return s;
}
int main() {
