	for (i = 0; i < N; i++) scanf("%lld", &in[i]);

	ll ans = 0;
	for (ll A = 1; A < N-1; A++) {
		for (int B = 1; B*B <= N-1-A; B++) {
			if ((N - 1 - A) % B) break;
			ans = max(ans, getans(N, A, A-(N - 1 - A) / B));
			ans = max(ans, getans(N, A, A-B));
		}
	}
	return !printf("%lld\n", ans);
}

