/**
 * list up v's divisors( O(sqrt(v)) )
 */
std::vector<uint64_t> divisor(uint64_t v)
{
  std::vector<uint64_t> ret;
  uint64_t fin = std::sqrt(v);

  for(uint64_t div = 1; div<=fin; div++) {
    if(v % div != 0) {
      div++;
      continue;
    }
    ret.push_back(div);
    ret.push_back(v/div);
  }
  ret.push_back(v);
  std::sort(ret.begin(), ret.end());
  return ret;
}

int main()
{
  uint64_t N;
  std::cin >> N;
  std::vector<int64_t> s(N);
  for(uint64_t i=0; i<N; i++) {
    std::cin >> s[i];
  }

  int64_t ret = 0; // A == N-1
  uint64_t max_A = N-1, max_B = 1;
  for(uint64_t A=2; A<N-1; A++) {
    auto divs = divisor(N - 1 - A);
    divs.pop_back();

    for(auto div: divs) {
      if(A <= div) continue;

      uint64_t B = A - div;
      // std::cout << "A: " << A
      //           << " N-1-A: " << N-1-A
      //           << " div: " << div
      //           << " B: " << B
      //           << std::endl;

      // calculate possible A and B
      if(A % (A-B) == 0) {
        if(2 * A <= N-1) continue;
      }

      uint64_t y = A;
      int64_t tmp = 0;
      while(y < N - 1) {
        tmp += s[y];
        y -= B;
        tmp += s[y];
        y += A;
      }
      // std::cout << "tmp: " << tmp << std::endl;

      if(ret < tmp) {
        ret = tmp;
        max_A = A;
        max_B = B;
      }
    }
  }

  // std::cout << "max_A: " << max_A << " max_B: " << max_B << std::endl;
  std::cout << ret << std::endl;

  return 0;
}

