  // (A-B)*k + A = N-1 or 
  // (A-B)*k = N-1
  int N;
  cin >> N;
  vector<int> S(N);
  REP(i, N) cin >> S[i];
  vector<vector<int>> divs(N + 1);
  for (int i = 1; i <= N; i++) {
    for (int j = i; j <= N; j += i) {
      divs[j].push_back(i);
    }
  }
  vector<bool> vis(N);
  vector<int> stk;
  const long long INF = 1e18;
  auto check = [&](int a, int b) {
    if (a <= b || b <= 0) return -INF;
    int x = 0;
    long long cost = 0;
    for (;;) {
      x += a;
      if (x == N - 1) break;
      if (x >= N || vis[x]) {
        cost = -INF;
        break;
      }
      vis[x] = true;
      stk.push_back(x);
      cost += S[x];
      x -= b;
      if (x == N - 1) break;
      if (x < 0 || vis[x]) {
        cost = -INF;
        break;
      }
      vis[x] = true;
      stk.push_back(x);
      cost += S[x];
    }
    while (!stk.empty()) {
      vis[stk.back()] = false;
      stk.pop_back();
    }
    return cost;
  };
  long long ans = 0;
  for (int A = 1; A <= N - 1; A++) {
    for (int k : divs[N - 1 - A]) {
      int B = A - (N - 1 - A) / k;
      ans = max(ans, check(A, B));
    }
    for (int k : divs[N - 1]) {
      int B = A - (N - 1) / k;
      ans = max(ans, check(A, B));
    }
  }
  cout << ans << '\n';
}

