int n;
int A[100001];
bool used[100001];
LL sub(int k) {
	int l = 0;
	int r = n;

	LL mx = 0;
	LL sum = 0;
	while (r >= 0) {
		if (used[l]) break;
		if (used[r]) break;
		if (l == r) break;
		sum += A[l];
		sum += A[r];
		used[l] = true;
		used[r] = true;

		l += k;
		r -= k;
		mx = max(mx, sum);
	}

	while (l > 0) {
		l -= k;
		r += k;
		used[l] = false;
		used[r] = false;
	}
	return mx;
}

