vector<int> divs(int n) {
  vector<int> res;
  for(int i = 1; i * i <= n; i++) {
    if(n % i == 0) {
      res.push_back(i);
      if(i != 1 && i * i != n) {
        res.push_back(n / i);
      }
    }
  }
  return res;
}

