              x++;
              continue;
            }
            bool ok = true;
            repr(j,1,x+1){
                if(st.find(j*i) != st.end() || st.find(j*i-i+A) != st.end()){
                    ok = false;
                    break;
                }
                st.insert(i*j);
                st.insert(i*j-i+A);
                now += s[i*j];
                now += s[i*j-i+A];
            }
            if(!ok){
                x++;
                continue;
            }
            ans = max(ans,now);
            x++;
        }    
    }
    cout << ans << endl;
}

