void solve(long long N, std::vector<long long> s){
	LL ret=0;
	for(int i=1;i<N;i++){
		int x=0;
		int y=N-1;
		LL sum=0;
		while(x+i<N){
			if(x+i==y){
				break;
			}
			x+=i;
			y-=i;
			if(x==y){
				break;
			}
			if(y<i){
				break;
			}
			sum+=s[x]+s[y];
		}
		ret=max(ret,sum);
	}
	cout << ret << endl;
}

