class Solve {
public:
    Int N;
    vector<Int> s;
    vector<Int> rui;

    // A + k*(A-B) == N

    void input(Int N_, vector<Int> s_) {
        N = N_;
        N--;
        s.resize(N + 1);
        rui.resize(N + 1);
        s = s_;
    }

    void input() {
        cin >> N;
        N--;
        s.resize(N + 1);
        rui.resize(N + 1);
        for (int i = 0; i <= N; ++i) {
            cin >> s[i];
        }
    }

    Int calc1(Int d) {
        for (int i = N; i >= 0; i -= d) {
            if (i + d > N) {
                rui[i] = s[i];
            } else {
                rui[i] = rui[i + d] + s[i];
            }
        }
        for (int i = N / d * d; i >= 0; i -= d) {
            if (i + d > N) {
                rui[i] = s[i];
            } else {
                rui[i] = rui[i + d] + s[i];
            }
        }


        auto check = [&](Int A) -> bool {
            if (A <= 0) return false;
            if (A - d <= 0) return false;
//            Int L = max((A - d) / d * 2 + 1, (N - A) / d * 2 + 1);
//            Int R = min((A - d) / d * 2 + 1, (N - A) / d * 2 + 1);
//            return L == R;
//            return (A + d - 1) / d * 2 > (N - A) / d * 2 + 1;
            Int las = N - A;
            if ((las - A) % d == 0 && A <= las) return false;
            return true;
        };

        Int ret = -INFl;
        for (Int A = N % d; A <= N; A += d) {
            if (!check(A)) continue;
            Int B = A - d;
            Int tmp = rui[A] + rui[A - B];
            if (N - A + d <= N) {
                tmp -= rui[N - A + d];
            }
            chmax(ret, tmp);
        }

        return ret;
    }

    Int calc2(Int d) {
        if (N % d) return -INFl;

        for (int i = N; i >= 0; --i) {
            if (i + d > N) {
                rui[i] = s[i];
            } else {
                rui[i] = s[i] + rui[i + d];
            }
        }

//        auto check = [&](Int A) -> bool {
//            Int L = max((A - d) / d * 2 + 1, (N - A) / d * 2 + 1);
//            Int R = min((A - d) / d * 2 + 1, (N - A) / d * 2 + 1);
//            return L >= R;
//        };

        Int ret = -INFl;
        for (Int A = d + 1; A <= N; ++A) {
//            if (!check(A)) continue;
            Int k = N / d;
            Int B = A - d;
            if (k * d + B >= N) {
                continue;
            }


            Int tmp = rui[A] + rui[A - B];
            if (k * (A - B) + A <= N) {
                tmp -= rui[k * (A - B) + A];
            }
            chmax(ret, tmp);

        }
        return ret;
    }

    Int fool() {
        Int ret = -INFl;
        Int bA, bB;
        for (Int A = 2; A <= N; ++A) {
            for (Int B = 1; B < A; ++B) {
                Int tmp = 0;
                set<Int> u;
                Int idx = 0;
                while (true) {
                    idx += A;
                    if (u.count(idx)) break;
                    u.insert(idx);
                    tmp += s[idx];
                    if (idx >= N) break;

                    idx -= B;
                    if (u.count(idx)) break;
                    u.insert(idx);
                    tmp += s[idx];
                    if (idx >= N) break;
                }
                if (idx == N) {
                    if (ret < tmp) {
                        ret = tmp;
                        bA = A, bB = B;
                    }
                }
            }
        }

        cout << ret << " " << bA << " " << bB << endl;
//        cout << ret << endl;
        return ret;
    }

    Int solve() {
//        input();

//        fool();


        Int ans = -INFl;
        for (int d = 1; d < N; ++d) {
            Int tmp = calc1(d);
            chmax(ans, tmp);
            Int tmp2 = calc2(d);
            chmax(ans, tmp2);
        }

        cout << ans << endl;
        return ans;


    }
};


