		ans = max(ans, cr);
	};
	n--;
	for (int k = 1; k <= n; k++) {
		for (int c = 0; c <= n / k; c++) {
			int a = n - k * c;
			int b = a - c;
			if (a > 0 && b >= 0 && a > b && a < n) {
				rlx(a, b, k); 
			}
		}
	}
	cout << ans << endl;
}

