vector<int> memoDs[100000+10];
vector<int> calcDs(int v) {
  vector<int> &ds = memoDs[v];
  if(ds.empty()) {
    for(int d = 1; d*d <= v; ++d) {
      if(v % d == 0) {
        ds.push_back(d);
        if(d*d != v) {
          ds.push_back(v/d);
        }
      }
    }
  }
  return ds;
}

ll calc(int a, int b) {
  if(a <= b) {
    // cerr << "HOGE" <<  " " << a << " " << b << endl;
    return -1;
  }
  if((n-1-b) % (a-b) != 0) {
    // cerr << "HOGE2" <<  " " << a << " " << b << endl;
    return -1;
  }
  ll k = (n-1-b) / (a-b);
  if(b % (a-b) == 0) {
    ll x = b / (a-b) + 1;
    if(x <= k-1) {
      // cerr << "HOGE3" <<  " " << a << " " << b << endl;
      return -1;
    }
  }
  // 落ちずに到着できる。
  ll res = 0;
  res += cs2[a-b][k-1];
  res += cs[a-b][k-1];
  // cerr << ">" << a << " " << b << " " << res << endl;
  return res;
}

