    cs[i].push_back(cur);
    for(int j = i; j < n; j += i) {
      cur += vs[j];
      cs[i].push_back(cur);
    }
  }
  for(int i = 1; i < n; ++i) {
    ll cur = 0;
    cs2[i].push_back(cur);
    for(int j = n-1-i; j >= 0; j -= i) {
      cur += vs[j];
      cs2[i].push_back(cur);
    }
  }

  ll res = 0;
  // for(int a = 2; a <= n-1; ++a) {
  //   int rem = (n-1) % a;
  //   if(rem == 0) {
  //     continue;
  //   }
