long long trial(long long a, long long b) {
    // cout << "trial: " << a << " " << b << endl;
    long long curr = 0;
    bool exists[n-1];
    memset(exists, 1, sizeof exists);
    long long phase = 0;
    long long score = 0;
    while (curr != n-1) {
        if (!exists[curr]) return LLONG_MIN;
        score += s[curr];
        exists[curr] = false;
        if (phase % 2 == 0) {
            curr += a;
        }
        else {
            curr -= b;
        }
        phase++;
    }
    return score;
}

