int const MAXN=110000;
int N;
int S[MAXN];

map<pair<int,int>,ll> f[MAXN];

ll get_sum(int s,int d,int k) {
	if (f[s].count({d,k})) return f[s][{d,k}];
	ll sum=0;
	rep(i,0,k+1) sum+=S[s+i*d];
	f[s][{d,k}]=sum;
	return sum;
}

ll check(int A,int B) {
	if (A<=B) return 0;

	int k=(N-1-A)/(A-B);
	if (A%(A-B)==0 && k>=A/(A-B)) return 0;

	return get_sum(0,A-B,k) + get_sum(A,A-B,k);
}

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(0);
	cout<<fixed<<setprecision(10);

