	ll res=0;
	rep(A,1,N) {
		int X=N-1-A;
		for (int d=1; d*d<=X; ++d) if (X%d==0) {
			if (A>d) res=max(res,check(A,A-d));
			if (A>X/d) res=max(res,check(A,A-X/d));
		}
	}

	cout<<res<<"\n";
}

