const int INF = 1 << 29;
const int MOD = 1e9 + 7;

const int N = 1e5 + 10;
int64 s[N];

int64 gcd(int64 a, int64 b) {
  while (b) {
    int64 c = a;
    a = b;
    b = c % b;
  }
  return a;
}

vector<int64> L[N], R[N];

int64 solve(int64 A, int64 B, int64 n) {
  int64 step = (n - A) / (A - B);
  int64 C = gcd(A, A - B);
  int64 mins = A / C;
  // trace(A, B, n, mins, step);
  if (mins <= step) return -1;
  // trace(A, B, step, L[A - B][step], R[A - B][step]);
  return L[A - B][step] + R[A - B][step];
}

int main() {
  int n;
  scanf("%d", &n);
  --n;
  for (int i = 0; i <= n; ++i) {
    scanf("%lld", &s[i]);
  }
  for (int k = 1; k < n; ++k) {
    int64 cur = 0;
    for (int i = 0; i <= n; i += k) {
      cur += s[i];
      L[k].push_back(cur);
    }
  }
  for (int k = 1; k < n; ++k) {
    int64 cur = 0;
    for (int i = 0; i <= n; i += k) {
      cur += s[n - i];
      R[k].push_back(cur);
    }
  }
  // for (int k = 1; k < n; ++k) {
  //   trace(k, sum[k].size());
  //   for (auto& it : sum[k]) {
  //     cout << it << " ";
  //   }
  //   cout << endl;
  // }
  int64 ret = 0;
  for (int A = 2; A < n; ++A) {
    int m = n - A;
    for (int C = 1; C * C <= m; ++C) {
      if (m % C) continue;
      int B = A - C;
      if (B > 0 && B < A) ret = max(ret, solve(A, B, n));
      B = A - m / C;
      if (B > 0 && B < A) ret = max(ret, solve(A, B, n));
    }
  }
  printf("%lld\n", ret);
  return 0;
}

