      {
        int B = A - d;
        if (B > 0 && (A % d != 0 || A / d > r / d)) {
          ans = max(ans, sumr[A][d] + suml[r][d]);
        }
      }
      {
        int B = A - r/d;
        if (B > 0 && (A % (r/d) != 0 || A / (r/d) > r / (r/d))) {
          ans = max(ans, sumr[A][r/d] + suml[r][r/d]);
        }
      }
    }
  }


  cout << ans << endl;

  return 0;
}

