#define rep(i, n) for (int i = 0; i < (n); i++)

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    ll ans = 0;
    vector<ll> s(n), t(n);
    rep(i, n) cin >> s[i];
    rep(i, n) t[i] = s[i] + s[n - 1 - i];

    vector<vector<ll>> dp(n, vector<ll>(n));

    forx(c, 1, n) rep(k, n)
    {
        if (c * (k + 1) >= n)
            break;
        if ((n - 1) % c == 0 && c * (k + 1) >= (n - 1) / 2)
            break;
        dp[c][k + 1] = dp[c][k] + t[c * (k + 1)];
    }

    rep(i, n) rep(j, n) ans = max(ans, dp[i][j]);

    cout << ans << endl;

    return 0;
}

