signed main(){
  Int n;
  cin>>n;

  vector<Int> s(n);
  for(Int i=0;i<n;i++) cin>>s[i];

  Int ans=0;
  vector<Int> cand;
  for(Int i=1;i*i<=n;i++){
    if((n-1)%i) continue;
    cand.emplace_back(i);
    cand.emplace_back((n-1)/i);
  }

  for(Int len:cand){
    vector<Int> vs;
    for(Int i=0;i<n;i+=len) vs.emplace_back(s[i]);
    Int m=vs.size();

    if(m<=3) continue;
    Int res=0;
    for(Int i=0;i*2<m;i++){
      if(i==m-(i+1)) break;
      res+=vs[i];      
      res+=vs[m-(i+1)];
      chmax(ans,res);      
    }

    using P = pair<Int, Int>;
    vector<P> vp;
    for(Int a=1;a<m;a++){
      Int d=m-1-a;
      for(Int i=1;i*i<=d;i++){
        if(d%i) continue;
        {
          Int k=i;
          Int b=a-(d/k);
          //cout<<a<<" "<<b<<endl;
          if(0<b&&b<a&&a>b*2&&__gcd(a,b)==1) vp.emplace_back(a-b,b);
        }
        {
          Int k=d/i;
          Int b=a-(d/k);
          //cout<<a<<" "<<b<<endl;
          if(0<b&&b<a&&a>b*2&&__gcd(a,b)==1) vp.emplace_back(a-b,b);
        }        
      }    
    }  
    vp=compress(vp);

    Int lst=0;
    vector<Int> cnt(m,0);
    for(auto p:vp){
      Int d=p.first;
      Int a=p.first+p.second;
      Int b=p.second;    
      Int k=(m-1-a)/(a-b);

      //cout<<a<<" "<<b<<endl;
      if(k<=100){
        Int pos=0,res=0;
        while(1){
          pos+=a;
          if(pos==m-1) break;
          res+=vs[pos];
          pos-=b;   
          res+=vs[pos];
        }
        chmax(ans,res);
        continue;
      }

      if(lst!=d){
        for(Int i=0;i<d;i++) cnt[i]=0;
        for(Int i=0;i<n;i++) cnt[i%d]+=vs[i];      
        lst=d;
      }
      //assert(a%d!=0);
      chmax(ans,cnt[0]+cnt[a%d]-(vs[a%d]+vs[m-1-b]));
    } 
  }
  cout<<ans<<endl;
  return 0;
}

