ll gcd(ll a, ll b) {
  if (b > a) {
    swap(a, b);
  }
  ll r = a%b;
  while (r != 0) {
    a = b;
    b = r;
    r = a%b;
  }
  return b;
}

ll lcm(ll a, ll b) {
  return (a / gcd(a, b))*b;
}

int n;
bool check(int a, int b) {
  int g = gcd(a, b);
  int a2 = a / g, b2 = b / g;
  if (a2 != b2 + 1) return true;
  int k = a2;
  if (k * a - (k - 1) * b < n - 1) return false;
  else return true;
}

