	int N; cin >> N;
	vll S(N); cin >> S;

	vvll suml(N), sumr(N);
	for (int i = 1; i < N; i++) {
		suml[i].push_back(0);
		for (int j = i; j < N; j += i) {
			suml[i].push_back(S[j] + suml[i].back());
		}
		sumr[i].push_back(0);
		for (int j = N-i-1; j >= 0; j -= i) {
			sumr[i].push_back(S[j] + sumr[i].back());
		}
	}

	ll maxv = 0;
	for (ll A = (N+1)/2; A < N-1; A++) {
		ll iA = N-1-A;
		ll div = gcd(A, iA);
		//divの約数列挙
		vll divisor;
		for (ll i = 1; i*i <= div; i++) {
			if (div % i == 0) {
				divisor.push_back(i);
				if (i != div/i) divisor.push_back(div/i);
			}
		}

		for (auto &d : divisor) {
			//cout << A << " " << d << endl;
			chmax(maxv, suml[d][iA/d] + sumr[d][iA/d]);
		}
	}

	cout << maxv << endl;
}

