    int f = N - 1;
    while (b < N && f >= 0 && b != f && f > d && S.find(b) == S.end() && S.find(f) == S.end())
    {
      t += s[b];
      t += s[f];
      S.insert(b);
      S.insert(f);
      ans = max(ans, t);
      b += d;
      f -= d;
    }
  }
  cout << ans << endl;
}

