  LL res=0;
  FOR(c,1,N-1) {
    LL cur=0;
    SETI viz;
    FOR(k,1,(N-1)/c) {
      LL a=k*c,b=N-1-k*c;
      if(b<=0||a>=N-1) break;
      if(viz.count(a)) break;
      viz.emplace(a);
      if(viz.count(b)) break;
      viz.emplace(b);
      cur+=S[a]+S[b];
//      dump(c,k,a,b,S[a],S[b],cur);
      SMAX(res,cur);
    }
  }
  cout<<res<<endl;
}

