long long solve(const vector<int>& s)
{
    int n = s.size();
    long long ans = 0;
    for(int diff=1; diff<=n/2; ++diff){
        long long sum = 0;
        int x = 0;
        int y = n - 1;
        for(int k=1; (k+1)*diff<n; ++k){
            x += diff;
            if(x == y)
                break;
            y -= diff;
            if(x == y)
                break;
            sum += s[x] + s[y];
            ans = max(ans, sum);
        }
    }
    return ans;
}

