template <typename T>
vector<T> divisors(T x){
    deque<T> dq;
    T s = sqrt(x);
    if (x % s == 0) {
        dq.push_front(s);
        T t = x / s;
        if (t > s) dq.push_back(t);
    }
    for (T n=s-1; n>=1; --n) {
        if (x % n == 0) {
            dq.push_front(n);
            dq.push_back(x / n);
        }
    }
    return vector<T>(dq.begin(), dq.end());
}


struct P {
    int cnt;
    ll vsum;
    ll vmax;
    bool stopped;
};
inline ostream& operator<<(ostream &s, P v)
{
    return s << "{ " << v.cnt << ", " << v.vsum << ", " << v.vmax << " }";
}

ll solve(int N, vi& s) {
    int W = N-1;
    int dmax = (W-1)/2;
    vector<P> lu(dmax+1, P {0,0,LLONG_MIN,false});

    ll ans = 0;
    for (int x=1; x<W; ++x) {
        vi di = divisors(x);
        ll sum = s[x] + s[N-1-x];
        for (int d: di){
            if (d > dmax) break;
            if (x == N-1-x) {
                lu[d].stopped = true;
                continue;
            }
            if (lu[d].stopped) continue;

            bool dy = (W % d == 0);

            int cnt = lu[d].cnt + 1;
            if (dy && d*cnt > dmax) {
                continue;
            }
            lu[d].cnt++;
            lu[d].vsum += sum;
            amax(lu[d].vmax, lu[d].vsum);
            amax(ans, lu[d].vmax);
        }
    }
    return ans;
}

