void solve() {
    i64 N = RD();
    auto A = RD_VEC(N);

    i64 ans = 0;
    FOR(c, 1, N-1) {
        i64 cur = 0;
        for(i64 k = 1; k*c < N-1; ++k) {
            i64 s = k*c;
            i64 t = N-1 - k*c;
            if((N-1)%c == 0 && s >= t) break;

            i64 b = t - c;
            if(b <= 0) break;

            cur += A[s] + A[t];
            chmax(ans, cur);
        }
    }

    PRINTLN(ans);
}

