ll f(int A, int B) {
	if (A == 2 * B) {
		return 0; 
	}
	ll res = 0;
	int now = 0;
	set <int> s;
	while (1) {
		now += A;
		if (s.find(now) != s.end()) {
			return 0;
		}
		s.insert(now);
		res += a[now];
		if (now == n - 1) {
			return res;
		}
		now -= B;
		if (s.find(now) != s.end()) {
			return 0;
		}
		s.insert(now);
		res += a[now];
		if (now == n - 1) {
			return res;	
		}
	}
}

