	while (scanf("%d", &n) != EOF) {
		for (int i = 0; i < n; ++i) {
			scanf("%d", a + i);
		}
		ll res = 0;
		for (int A = 1; A < n - 1; ++A) {
			int m = n - 1 - A;
			for (int i = 1; 1ll * i * i <= m; ++i) { 
				if (m % i == 0) {
					int x = i, y = m / i;
					if (x < A) {
						res = max(res, f(A, A - x)); 
						//printf("%d %d %lld\n", A, A - x, res);
