void solve(){
  int n; cin >> n;
  V<ll> s(n); cin >> s;
  ll ans = 0;
  FOR(c,1,n){
    if((n-1) % c == 0 ) continue;
    V<ll> dp(n+10, 0); 
    FOR(k,0,n){
      if(k*c>n-1) break;
      if(c*(k+1)>n-1 || n-1-c*(k+1)<0 ) break;
      dp[k+1] = dp[k] + s[c*(k+1)] + s[ n-1-c*(k+1) ];
      ans = max(ans, dp[k+1]);
    }
  }
  ncoutn(ans);
}


