    cand.emplace_back((n-1)/i);
  }

  for(Int len:cand){
    vector<Int> vs;
    for(Int i=0;i<n;i+=len) vs.emplace_back(s[i]);
    Int m=vs.size();
    if(m<=3) continue;
    Int res=0;
    for(Int i=0;i*2<m;i++){
      if(i==m-(i+1)) break;
      res+=vs[i];      
      res+=vs[m-(i+1)];
      chmax(ans,res);      
    }

    using P = pair<Int, Int>;
    vector<P> vp;
    for(Int a=1;a<m;a++){
      Int d=m-1-a;
      for(Int i=1;i*i<=d;i++){
        if(d%i) continue;
        {
          Int k=i;
          Int b=a-(d/k);
          //cout<<a<<" "<<b<<endl;
          if(0<b&&b<a&&a>b*2&&b+1!=a&&__gcd(a,b)==1) vp.emplace_back(a-b,b);
