    ll ans = 0;
    for (int d = 1; d < N - 1; d++) {
        ll t = 0;
        for (int k = 0; k * d < N - 1; k++) {
            used[k * d] = true;
            if (used[N - 1 - k * d]) {
                break;
            }
            t += s[k * d] + s[N - 1 - k * d];
            ans = max(ans, t);
        }
        for (int k = 0; k * d < N - 1; k++) {
            used[k * d] = false;
        }
    }

    return ans;
}

