ll N;
vector<ll> S;

signed main()
{
    cin >> N;
    S.resize(N);
    REP(i, N) { cin >> S[i]; }

    ll ans = 0;

    // C = A - B とすると、
    // B 移動では C * 0 .. C * k の場所を取得でき、
    // A 移動では A + C * 0 .. A + C * k の場所を取得する
    // C, k を全探索する
    for(ll C = 1; C < N; ++C) {
        ll prev_val_a = 0;      // A 移動によって取得した数の和
        ll prev_ind_a = N-1;    // 1 つ前のループで遷移した S のインデックス
        ll prev_val_b = 0;      // B 移動によって取得した数の和
        ll prev_ind_b = 0;      // 1 つ前のループで遷移した S のインデックス

        // A + C * k = N - 1 より、 k = ((N - 1) - A) / C なので k は N / C くらいまでのループを
        // 見ればよい
        for(ll k = 1; k < N / C; ++k) {
            // C を固定した場合、1 つ前のループの値が使いまわせる
            ll A = N - 1 - C * k;
            ll B = A - C;
            if(A <= 0 || B <= 0 || A <= B) { continue; }
            prev_ind_b += C;
            prev_val_b += S[prev_ind_b];

            // A 移動でとる位置と B 移動でとる位置がかぶったらだめ
            // -> C が N - 1 の約数の場合
            if((N - 1)  % C == 0 && prev_ind_a == prev_ind_b) { break; }
            prev_ind_a -= C;
            prev_val_a += S[prev_ind_a];

            if((N - 1) % C == 0 && prev_ind_a == prev_ind_b) { break; } // 念のため・・。
            if(prev_ind_a <= 0 || prev_ind_b >= N - 1) { break; }

            ans = max(ans, prev_val_a + prev_val_b);
        }
    }

    printf("%lld\n", ans);

    return 0;
}

