  ll ans = 0;
  for (int C = 1; C < N; ++C) {

    ll tmp = 0, ma = 0;
    int lb = 0, ub = N-1;
    while (lb <= N-1 && ub >= 0) {
      if (ub == lb || (lb-ub) == C) break;
      tmp += S[ub] + S[lb];
      ma = max(ma, tmp);
      lb += C; ub -= C;
    }

    ans = max(ans, ma);
  }

  cout << ans << endl;

  return 0;
}

