long long func(int sub, int k) {
    int A = N - 1 - k * sub;
    if (A <= 1) {
        return NEG_INF;
    }
    if (A - sub <= 0) {
        return NEG_INF;
    }
    if (A % sub == 0 && A*2 <= N - 1) {
        return NEG_INF;
    }

    if (k == 0) {
        return 0;
    }

    if (dp[sub].find(k) != dp[sub].end()) {
        return dp[sub][k];
    }

    long long ret;
    if (k*sub != N-1-k*sub) {
        ret = func(sub, k - 1) + S[k*sub] + S[N-1-k*sub];
    } else {
        ret = NEG_INF;
    }

    //long long ret = func(sub, k - 1) + S[k*sub] + S[N-1-k*sub];

    dp[sub][k] = ret;
    return ret;
