    i64 N;
    cin >> N;

    vector<i64> s(N);
    rep(i,0,N){
        cin >> s[i];
    }

    i64 ans=0;
    vector<i64> acc(N); // mod xでの累積和
    rep(x,1,N){
        i64 d=(N-1)%x;
        rep(i,1,N){
            i64 j=i*x+d;
            if(j>=N) break;
            acc[j]=acc[j-x]+s[j];
        }

        i64 sum=0;
        rep(k,0,N){
            i64 pk=k*x;
            if(pk>=N-1) break;

