                if (pk + b >= N - 1) continue;
                if (a <= pk and b % (a - b) == 0) continue;
            }

            i64 add=acc[k*x+b]-acc[b];
            chmax(ans,sum+add);
        }
    }

    cout << ans << endl;
}

