    fraction(int bunshi,int bunbo):bo(bunbo),shi(bunshi){
        if(bunbo&&bunshi){
            int g=gcd(bo, shi);
            bo/=g;
            shi/=g;
        }
    };
    explicit inline operator double()const { return (double)shi/(double)bo; }
    explicit inline operator long double()const { return (long double)shi/(long double)bo; }
};
