ll solve(ll *s, int c,int N){
    ll ans = 0;
    ll temp = 0;
    int left = 0;
    int right = N-1;
    while(true){
        temp += s[left] + s[right];
        ans = max(temp,ans);
        left += c;
        right -= c;
        if(right == left || right == left-c) break;
        if(right<0) break; 
    }
    return ans;
}

