template<typename V, typename H> void resize(vector<V> &vec,
        const H head
) {
    vec.
            resize(head);
}
template<typename V, typename H, typename ... T> void resize(vector<V> &vec,
        const H &head,
        const T ... tail
) {
    vec.
            resize(head);
    for (
        auto &v
            : vec)
        resize(v, tail
                ...);
}
