template<class T> auto sorti(vector<T> &a) {
    int n = sz(a);
    vp ret(n);
    rep(i, n)ret[i] = P(a[i], i);
    sort(ret);
    return ret;
};
template<class T> auto rsorti(vector<T> &a) {
    int n = sz(a);
    vp ret(n);
    rep(i, n)ret[i] = P(a[i], i);
    rsort(ret);
    return ret;
};
