#include <bits/stdc++.h>
using namespace std;
using ll = long long;

void solve(long long N, std::vector<long long> s)
{
    // A - B = CとおいてCについて考える
    // 経由する番号は順に
    // 0, A, C, A+C, 2C, A+2C, …, kC, A+kC(=N-1)
    ll ans = 0;
    for (ll c = 1; c <= N; c++) {
        ll score = 0;
        set<ll> passed;

        for (ll k = 0; k * c < N - 1; k++) {
            auto a = N - 1 - k * c; // A + kC = N - 1 より
            if (a <= c) {
                // A - B = C → B = A - C
                // Bが1以上であるためにはA>Cでなければならない
                break;
            }
            auto l = k * c; // 0, C, 2C, …, kCの列
            auto r = N - 1 - k * c; // A, A+C, A+2C, …, A+kCの列
            if (l == r || passed.count(l) > 0 || passed.count(r) > 0) {
                // すでに通った蓮は使えない
                break;
            }
            score += s[l] + s[r];
            passed.insert(l);
            passed.insert(r);
            ans = max(ans, score);
        }
    }
    cout << ans << endl;
}

