long long solve(){
    long long ans = 0;
    for(int i = 1;i < n;++i){
        long long nowx = 0,nowy = n -1,nowc = 0;
        while(i < nowy){
            nowc += s[nowx] + s[nowy];
            ans = max(ans,nowc);
            nowx += i;
            nowy -= i;
        }
    }
    return ans;
}

