template<typename T>
class CumulativeSum{
public:
  Int n;
  vector<T> sum;
  vector<T> A;
  Int added;
  CumulativeSum():n(-1),added(0){}
  CumulativeSum(Int n):n(n), sum(n+1), A(n+1),added(0){}
  CumulativeSum(const vector<T> &B):n(B.size()), sum(n+1), A(n+1),added(0){
    for(Int i=1;i<=n;i++) sum[i] = sum[i-1] + B[i-1];
  }

  void apply(){
    for(Int i=1;i<=n;i++) A[i] = A[i] + A[i-1];
    for(Int i=1;i<=n;i++) A[i] = A[i] + A[i-1];
    for(Int i=1;i<=n;i++) sum[i] = sum[i] + A[i-1];
    added = 0; A.clear(); A.resize(n+1);
  }

  //[l, r)にxを加算
  void add(Int l, Int r, T x){
    added = 1;
    assert(l <= r && 0 <= l && r <= n);
    A[l] = A[l] + x;
    A[r] = A[r] - x;
  }

  //[l, r)の和を得る
  T get(Int l,Int r){
    assert(l<=r && 0<=l && r<=n);
    if(added) apply();
    return sum[r] - sum[l];
  }
};


vector<vector<P> > getAB(Int N){
  vector<vector<P> > res(N);
  for(Int x=1;x<N;x++){ //x = A - B
    Int B = N % x == 0? x:N % x;
    Int A = B + x;
    assert((N - A)%x == 0);
    assert((N - B)%x == 0);
    while(A <= N && B <= N){
      res[x].push_back(P(A, B));
      A += x, B += x;
    }
  }
  return res;
}

Int N;
vector<Int> s;
Int calcL(Int x, Int l, Int r){
  static CumulativeSum<Int> sum;
  static Int px = -1;
  if(px != x){
    px = x;
    sum = CumulativeSum<Int>(N);
    for(Int i=0;i<N;i+=x) sum.add(i, i+1, s[i]);
  }
  return sum.get(l, r);
}

Int calcR(Int x,Int l, Int r){
  static CumulativeSum<Int> sum;
  static Int px = -1;
  if(px != x){
    px = x;
    sum = CumulativeSum<Int>(N);
    for(Int i=0;i<N;i+=x) sum.add(i, i+1, s[N - 1 - i]);
  }
  return sum.get(l, r);
}

Int calc(Int A, Int B){
  Int x = A - B;
  if(!(((N-1) % x != 0) || ((N-1) % x == 0 && A * 2 > N-1))) return -INF;
  if(A == N-1) return s[N-1];
  Int a = calcL(x, 0, N - A);
  Int b = calcR(x, 0, N - A);
  return a + b;
}

Int calc2(Int A,Int B){
  Int x = 0;
  Int res = 0;
  set<Int> used;
  while(1){
    x = x + A;
    res += s[x];
    if(x == N - 1) return res;
    assert(x >= 0 && x < N);
    if(used.count(x)) return -INF;
    used.insert(x);

    x = x - B;
    res += s[x];
    if(x == N - 1) return res;
    assert(x >= 0 && x < N);
    if(used.count(x)) return -INF;
    used.insert(x);
  }
}

