long S[100000]; 
void Calc(){
	int N = rei();
	//(A-B)*k
	//N-1 - (A-B)*k
	//N-1-A = (A-B)*(K-1)
	for(int i=0;i<N;i++){
		S[i] = rei();
	}
	long ans = 0;
	for(int i=2;i<=N-1;i++){
		if((N-1) % i == 0){
			continue;
		}
		long sum = 0;
		for(int j=0;j<N;j+=i){
			sum += S[j] + S[N-1-j];
			ans = max(ans,sum);
		}
	}
	cout << ans << endl;
}
