int main() {
  std::ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int N;
  cin >> N;

  VI S(N);
  for (int i = 0; i < N; ++i) {
    cin >> S[i];
  }

  auto mkCum = [&](VI &s) {
    V<V<ll>> cum(N + 1);
    for (int m = 1; m < N; ++m) {
      int x = m;
      cum[m].push_back(0);
      while(x < N) {
        cum[m].push_back(*cum[m].rbegin() + s[x]);
        x += m;
      }
    }
    return cum;
  };

  auto Lcum = mkCum(S);
  reverse(S.begin(), S.end());
  auto Rcum = mkCum(S);

  debug_dim2(Lcum);
  debug_dim2(Rcum);

  ll ans = 0ll; // 最悪Nジャンプすればいい
  for (int m = 1; m < N; ++m) {
    for (int rlen = 1; rlen < Rcum[m].size(); ++rlen) {
      int llen = rlen;
      if ((llen + rlen + 1) * m < N) {
        ans = max(ans, Rcum[m][rlen] + Lcum[m][llen]);
      }
    }
  }

  cout << ans;

  return 0;
}

