using namespace std;
typedef long long ll;
int N;
ll S[100010];

int main(){
    cin >> N;
    for(int i=0;i<N;i++) cin >> S[i];
    ll ans = 0;
    for(int C=1;C*C<=N-1;C++){
        if((N-1)%C!=0) continue;
        ll now = 0;
        for(int k=1;k*C<=N-1;k++){
            int A = N-1-k*C,B = A-C;
            now = now+S[N-1-k*C]+S[k*C];
            if(A==2*B || B<=0) continue;
            ans = max(ans,now);
        }
        int C2 = (N-1)/C;
        now = 0;
        for(int k=1;k*C2<=N-1;k++){
            int A = N-1-k*C2,B = A-C2;
            now = now+S[N-1-k*C2]+S[k*C2];
            if(A==2*B || B<=0) continue;
            ans = max(ans,now);
        }
    }
    cout << ans << endl;
}

