                    gap1 -= sum1[j][(long long)sum1[j].size() - (N - A - 1) / j - 2];
                }
                long long gap2 = sum2[j][0];
                if((N - A - 1) / j + 1 < (long long)sum2[j].size()){
                    gap2 -= sum2[j][(N - A - 1) / j + 1];
                }
                ans = max(ans, gap1 + gap2);
            }
            j = jj;
        }
    }
    printf("%lld\n", ans);
    return 0;
