			if (A2 <= k * C) continue;
			if (!((usedIndexSet.count(k * C) == 0) and (usedIndexSet.count(A2 ) == 0))) {
				break;
			}

			usedIndexSet.insert(k * C);// k=1 のとき、CとA2が追加される。
			usedIndexSet.insert(A2);
			score += S[k * C];
			score += S[A2];
			chmax(ans, score);

			nowA =A2;
			// A2 + (k+1)C = N-1
			// A2 +C = A となる。

		}
	}
	cout << ans << endl;

}

