      for (int k = 1; k * C < N; k++) {
        sum += S[k * C] + S[N - 1 - k * C];
        if (safe(N, C, k)) {
          chmax(res, sum);
        }
      }
    }
    cout << res << endl;
  }
  return 0;
}

