        cin >> s[i];
    --n;
    ll ans = 0;
    for (int c = 1; c < n; ++c) {
        for (int i = 1; i * c <= n; ++i) 
            f[i] = f[i-1] + s[i*c];
        g[0] = s[n%c];
        int j=0;
        for (int i = 1; n%c+i * c <= n; ++i) {
            g[i] = g[i-1] + s[i*c+n%c];
            j = i;
        }
        for (int a = n%c; a < n; a += c) {
            int k = (n-a)/c;
            int l = a/c-1;
            if (n%c != 0 || l+1>k)
                ans = max(ans, f[k] + g[j] - (l>=0?g[l]:0));
        }
    }
    cout << ans << endl;
}

