void solve(void)
{
  int N;
  cin>>N;
  vector<int> S(N);
  for (int i = 0; i < N; i++)
  {
    cin>>S[i];
  }
  int ANS = 0;
  for (int C = 0; C < N; C++)
  {
    int SCORE = 0;
    set<int> st;
    for (int X = 0; X < N; X++)
    {
      if(X*C > N)break;
      int A = (N-1) - X*C;
      if(A <= C)break;
      int P1 = X*C;
      if(st.insert(P1).second == false) break;
      SCORE += S[P1];
      int P2 = N-1 - X*C;
      if(st.insert(P2).second == false) break;
      SCORE += S[P2];
      // DEBUG(SCORE);
      chmax(ANS,SCORE);
    }

  }

  cout<<ANS<<endl;



  return;
}


