void solve(long long N, std::vector<long long> s){
  ll ans = 0;
  for(ll d = 1; d < N-1; d++){
    ll l,r;
    l = 0;
    r = N-1;
    ll wa = 0;
    if((N-1)%d==0){
      while(true){
        if(r-d<=0) break;
        wa += s[l];
        wa += s[r];
        chmax(ans,wa);
        dump(l,r,wa);
        dump(r,r-d);
        l += d;
        r -= d;
        if(l>=r) break;
      }
    }else{
      while(true){
        if(r-d<=0) break;
        wa += s[l];
        wa += s[r];
        chmax(ans,wa);
        dump(l,r,wa);
        dump(r,r-d);
        l += d;
        r -= d;
        if(l>N-1 || r<0) break;
      }
    }
  }
  cout << ans << endl;
}

