void solve(){
  int n; cin >> n;
  V<ll> s(n); cin >> s;
  ll ans = 0;
  FOR(c,1,n){

    ll dppre=0, dp=0;
    FOR(k,0,n){
      swap(dp, dppre);
      if(k*c>n-1) break;
      if((n-1) % c == 0 && (k+1)*c>=(n)/2) break;
      if(c*(k+1)>n-1 || n-1-c*(k+1)<0 ) break;
      dp = dppre + s[c*(k+1)] + s[ n-1-c*(k+1) ];
      ans = max(ans, dp);
    }
  }
  ncoutn(ans);
}


