int check(int A, int delta){
    int m = (n - A - 1) / delta;
    if (delta >= A) return -1;
    if (A % delta == 0){
        if (A / delta <= m) return -1;
        return ls[delta][m] + rs[delta][m];
    }
    return ls[delta][m] + rs[delta][m];
}
