void solve(){
  int n; cin >> n;
  V<ll> s(n); cin >> s;
  ll ans = 0;
  if( n > 500 ){
  FOR(c,1,n){

    ll dppre=0, dp=0;
    FOR(k,0,n){
      swap(dp, dppre);
      if(k*c>=n-1) break;
      if((n-1) % c == 0 && (k+1)*c>=(n-1)/2) break;
      if(c*(k+1)>n-1 || n-1-c*(k+1)<0 ) break;
      dp = dppre + s[c*(k+1)] + s[ n-1-c*(k+1) ];
      ans = max(ans, dp);
    }
  }
  }else{

    FOR(a,0,n){
    FOR(b,0,a){
      ll tmp = 0;
      int pos = 0, t = 0;
      V<bool> sw(n);sw[0] = true;
      while(pos<n){
        if(t) pos -= b;
        else pos += a;
        if(pos<0 || pos>=n || sw[pos]) { tmp = -1; break;}
        tmp += s[pos];
        sw[pos] = true;
        t ^= 1;
        if(pos==n-1) break;
      }
      //ncouts(a); ncouts(b); ncoutn(tmp);
      ans = max(ans, tmp);
    }
  }

  }
  ncoutn(ans);
}


