int main()
{
	int N;
	cin >> N;
	for (auto i = 0; i < N; ++i)
	{
		cin >> s[i];
	}

	for (auto i = 0; i * i <= N - 1; ++i)
	{
		for (auto j = 0; j < i; ++j)
		{
			auto temp = 0ll;
			for (auto k = N - 1 + j; k >= 0; k -= i)
			{
				temp += s[k];
				sum[i][j].push_back(temp);
			}
		}
	}

	auto result = 0ll;
	for (auto A = 2; A < N - 1; ++A)
	{
		auto remain = N - A - 1;
		for (auto d = 1; d * d <= remain && (d < A); ++d)
		{
			if ((remain % d) != 0)
			{
				continue;
			}

			auto B = A - d;
			if ((B % d == 0) && (remain / d) > (B / d))
			{
				continue;
			}
			auto sumA = sum[d][0][remain / d];
			auto sumB = sum[d][A % d][(N - 1) / d] - sum[d][A % d][(A / d) - 1];
			result = max(result, sumA + sumB);
		}
		if(remain < A)
		{
			auto sumA = s[A];
			auto sumB = s[N - 1 - A];
			result = max(result, sumA + sumB);
		}
	}

	cout << result << endl;

	return 0;
}

