    READVEC(S);

    lint ret = 0;
    for (int i = 1;i <= N - 1; i++) {
        int ai = (N - 1) % i;
        for (int A = ai;A <= N - 1;A += i) {
            if (A == 0)
                continue;
            if ((i + 1) * 1LL * A + 1 <= N)
                continue;

            lint B = (i + 1) * 1LL * A + 1 - N;
            if (B % i != 0 || B / i >= A)
                continue;
            B = B / i;

            lint total = 0;
            set<int> seen;
            int good = 1, pos = 0, turn = 0;
            while (pos != N - 1) {
                if (pos >= N || pos < 0 || seen.count(pos))
                {
                    good = 0;
                    goto done;
                }

                seen.insert(pos);
                total += S[pos];

                if (turn == 0) {
                    pos += A;
                } else pos -= B;
                turn = 1 - turn;
            }
done:
            if (good)
                ret = max(ret, total);
        }
    }

    cout << ret << endl;
    return 0;
};

