const int MAX = 1e5+10;

int N;
ll s[MAX];

ll solve() {
    ll ans = 0;
    FOR (c, 1, N) {
        ll score = 0;
        ll k = 1;
        set<int> pos;
        while (k*c < N) {
            int a = N-1-k*c;
            int b = a-c;
            if (b <= 0 || b >= a) break;
            if (a == N-1-a || pos.find(a) != pos.end() || pos.find(N-1-a) != pos.end()) {
                break;
            }
            score += s[a];
            score += s[N-1-a];
            ans = max(ans, score);
            pos.insert(a);
            pos.insert(N-1-a);
            k++;
        }
    }
    return ans;
}

