int main(){
	cin.tie(0); cin.sync_with_stdio(0);

	int n; cin >> n;
	vi s(n); rep(i, n) cin >> s[i];

	ll ans = 0;
	vector<ll> dp(n);
	for(int k = 1; k < n - 1; k++){
		vector<ll> next(1);
		for(int c = 1; k * c < n; c++){
			ll cost = dp[c] + s[n - 1 - k * c] + s[k * c];
			if(k * c < n - 1 - k * c || (n - 1) % c != 0) ans = max(ans, cost);
			next.pb(cost);
		}
		dp = next;
	}

	cout << ans << endl;

	return 0;
}

