    fisi, fisd, fdsi, fdsd, sifi, sifd, sdfi, sdfd
};
inline void sort(vector<P> &a, ___pcomparator
type) {
    switch (type) {
        case fisi:
            sort(all(a),
                 [&](
                         P l, P
                 r) {
                     return l.fi != r.fi ? l.fi < r.fi : l.se < r.
                             se;
                 });
            break;
        case fisd:
            sort(all(a),
                 [&](
                         P l, P
                 r) {
                     return l.fi != r.fi ? l.fi < r.fi : l.se > r.
