ll score( const vector<ll>& s, ll a, ll b, ll n )
{
	ll cur = 0;
	ll ret = 0;
	while( cur < n )
	{
		cur += a;
		ret += s[cur];
		if( cur == n - 1 ) break;
		cur -= b;
		ret += s[cur];
	}
	return ret;
}

template <typename T>
vector<T> divisor( T n )
{
	vector<T> res;
	for( T i = 1; i * i <= n; ++i )
	{
		if( n % i == 0 )
		{
			res.push_back( i );
			if( i != n / i ) res.push_back( n / i );
		}
	}
	sort( ALL( res ) );
	return res;
}

template <typename T>
T gcd(T a, T b)
{
	if (a < b)
		swap(a, b);
	return b ? gcd(b, a % b) : a;
}

