int main(){
	scanf("%d",&n);
	FOR(i,n) scan(s[i]);
	for(int c=1;c<n-1;c++){//枚举每一个c，c的范围就是[1,n-2]. 不可能为n-1，A=N B=1是不成立 
		ll temp=0;
		l=0,r=n-1;
		cnt++;//cnt 的作用就是防止走到了空的地方 
		//对k进行枚举 
		while(l!=r&&r>c&&l<n-1&&x[l]!=cnt&&x[r]!=cnt){
			temp+=s[l];temp+=s[r];
			x[l]=x[r]=cnt;
