    vll s(N);
    rep(i, N)cin >> s[i];

    ll ans = LLONG_MIN;
    set<int> T;
    for (int i = 1; i <= N - 1; ++i) { // A-B
        T.clear();
        ll sum = 0;
        for (int j = 0; i*j < N - 1; ++j) { // j turns
            int A = N - 1 - i * j;
            int B = A - i;
            if (B <= 0)break;
            if (T.count(i*j))break;
            T.insert(i*j);
            sum += s[i*j];
            if (T.count(N - 1 - i * j))break;
            T.insert(N - 1 - i * j);
            sum += s[N - 1 - i * j];
            smax(ans, sum);
        }
    }
    cout << ans << endl;
}

