    cin.tie(0);
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<ll> s(n);
    for (int i = 0; i < n; i++) {
        cin >> s[i];
    }

    vector< vector<int> > vv(n);
    //int counter = 0;
    for (int i = 1; i < n - 1; i++) {
        for (int j = i; j < n; j += i) {
            vv[j].push_back(i);
            //counter++;
        }
    }
    //cerr << counter << endl;

    ll ans = 0;
    for (int a = 1; a < n - 1; a++) {
        int hoge = n - 1 - a;
        for (int x : vv[hoge]) {
            if (x >= a) break;
            if (a % x == 0 && a / x <= (n - 1 - a) / x) continue;
            ll sum = 0;
            for (int i = 0; i + a < n; i += x) {
                sum += s[i] + s[i + a];
            }
            ans = max(ans, sum);
        }
    }
    cout << ans << endl;
    return 0;
}

