            i64 a=(N-1)-pk;
            if(a<=0 or N<=a) continue;

            i64 b=a-x;
            if(b<=0 or (k>=1 and b>=a)) continue;

            bool ok=true;
            i64 tmp=0;
            if(k>=1) {
                if(((N-1)-a)%k!=0) continue;
                i64 b2=a-((N-1)-a)/k;
