	return sum;
}

ll check_naive(int A,int d) {
	if (A<=d) return 0;
	int k=(N-1-A)/d;
	if (A%d==0 && k>=A/d) return 0;
	return get_sum_naive(0,d,k) + get_sum_naive(A,d,k);
}

