void check(int i, int A)
{
    if (2 * i >= A)
        return;
    int B = A - i;
    if (B >= A)
        return;
    ll res = summ[i] + summ2[i];
    if (res > ans)
    {
        ans = res;
    }
    //cout << i << " " << A << " " << res << endl;
