        }
    }
    reverse(v, v + n);
    for (int i = 1; i < n; i++)
    {
        for (int j = 0; j * i < n; j++)
        {
            summ2[i] += v[i * j];
        }
    }
    reverse(v, v + n);
    ll dist = n - 1;
    for (int A = 1; A <= n - 1; A++)
    {
        ll dementor = dist - A;
        for (int i = 1; i * i <= dementor; i++)
