int const MAX_N = 512 * 1024;
long long const LL_INF = 5000000000000000000LL;

long long s[MAX_N];
int nnew[MAX_N];
int FLAG = 0;

struct pp {
	int a, b;
	int calc;
	pp() {}
	pp(int aa, int bb, int n) {
		a = aa;
		b = bb;
		int df = a - b;
		calc = (n - 1) / df + (n - 1 - a) / df;
	}
};

bool operator < (const pp& a, const pp& b) {
	return a.calc < b.calc;
}

vector<pp> ms;

int main() {
	clock_t t_BG = clock();

	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%lld", &s[i]);

	long long mx = 0;
	long long iter = 0;

	for (int df = 1; df < n; df++) {
		int bg = df + 1, en = n - 2, a_go = +1;
		int rem = (n - 1) % df;
		int init_rem = rem;
		if (rem != 0) {
			if (rem < df + 1) rem += df;
			bg = rem;
			en = n - 2;
			a_go = df;
		}

		for (int a = bg; a <= en; a += a_go) {
			int EE = (n - 1 - a) / df;
			int FF = (n - 1) / df;
			if (init_rem == 0 && EE < FF - 5) break;

			int b = a - df;

			if (a > 0 && b > 0)
				ms.push_back(pp(a, b, n));
		}
	}

	sort(ms.begin(), ms.end());

	for (int ee=0; ee<(int) ms.size(); ee++) {
		int a = ms[ee].a;
		int df = ms[ee].a - ms[ee].b;

		iter++;

		FLAG++;
		long long sum = 0;
		int x = 0;
		int fail = 0;
		int cnt = 0;
		while (1) {
			if (x == n - 1) break;
			if (x < 0 || x > n - 1) {
				fail = 1;
				break;
			}
			if (nnew[x] == FLAG) {
				fail = 1;
				break;
			}
			sum += s[x];
			nnew[x] = FLAG;
			if (cnt % 2 == 0) x += a;
			else x -= a - df;
			cnt++;
		}
		if (!fail) 
			mx = max(mx, sum);

		if (iter & 128) {
			if (((double)(clock() - t_BG)) / (CLOCKS_PER_SEC) > 1.85) {
				cout << mx;
				return 0;
			}
		}
	}

	cout << mx;
	return 0;
}

