const int MAX_N = 1e5;
const ll INF = 1e18;

int N;
int s[MAX_N];

ll solve() {
    vector<bool> used(N - 1);
    ll ans = -INF;
    for (int d = 1; d < N - 1; d++) {
        ll t = 0;
        for (int k = 0; k * d < N - 1; k++) {
            if (used[k * d] || used[N - 1 - k * d] || k * d == N - 1 - k * d) {
                break;
            }
            used[k * d] = used[N - 1 - k * d] = true;
            t += s[k * d] + s[N - 1 - k * d];
            ans = max(ans, t);
            if (t > 3) {
                cerr << k << ", " << d << endl;
            }
        }
        for (int k = 0; k * d < N - 1; k++) {
            used[k * d] = used[N - 1 - k * d] = false;
        }
    }

    return ans;
}

