int LiangJiaJun(){
    scanf("%d",&n);
    for(int i=0;i<n;i++)scanf("%d",&a[i]);
    for(int i=1;i<n;i++){
        ll now=0;
        if((n-1)%i!=0){
            int qc=(n-1)/i+1;
            int B=qc*i-(n-1);
            int A=B+i;
            for(int j=i;j<n;j+=i){
                now+=a[j];
                if(j+B<n)now+=a[j+B];
            }
            ans=max(ans,now);
        }
        else{
            f.clear();
            f.push_back(0);
            now=0;
            for(int j=0;j*i<n-1;j++){
                if(j*i==n-1-j*i)break;
                if(j*i==n-1-(j-1)*i)break;
                if(n-1-j*i==(j-1)*i)break;
                f.push_back(f[j]+a[n-1-j*i]+a[j*i]);
                now=max(now,f[j+1]);
            }
            ans=max(ans,now);
        }
    }
    printf("%lld\n",ans);
    return 0;
}

