  cin >> N;
  vector<ll> s(N);
  for (auto i = 0; i < N; ++i)
  {
    cin >> s[i];
  }
  ll ans{0};
  for (auto C = 1LL; C < N; ++C)
  {
#if DEBUG == 1
    cerr << "C = " << C << endl;
#endif
    ll score{0};
    set<int> S;
    for (auto x = 0LL; x < N; ++x)
    {
      ll A{N - 1 - x * C};
      ll L{x * C};
      ll B{A - C};
      if (!(0 <= A && A < N && 0 <= L && L < N))
      {
        break;
      }
      if (A == L || S.find(A) != S.end() || S.find(L) != S.end())
      {
        break;
      }
      if (B <= 0)
      {
        break;
      }
      score += s[A] + s[L];
#if DEBUG == 1
      cerr << "s[" << A << "] = " << s[A] << endl;
      cerr << "s[" << L << "] = " << s[L] << endl;
#endif
      ch_max(ans, score);
      S.insert(A);
      S.insert(L);
    }
  }
  cout << ans << endl;
}

