int main() {
	int n;
	cin >> n;

	vector<int> s(n, 0);
	for (int i = 0; i < n; i++) {
		cin >> s[i];
	}

	// a > 0
	// b > 0
	// c = a - b: b = a - c > 0
	// a + kc = n - 1

	long long ans = 0;
	int c = 1;
	while (c < n - 1) {
		int k = 0;
		while (1) {
			int a = n - 1 - k * c;
			if (a <= 0 || a <= c) {
				break;
			}

			long long sum = s[a];
			set<int> s_pos = {a};
			for (int i = 1; i <= k; i++) {
				int ic = i * c;
				if (s_pos.count(ic) > 0 || s_pos.count(ic + a) > 0) {
					sum = -1;
					break;
				}
				sum += s[ic];
				sum += s[ic + a];
				s_pos.insert(ic);
				s_pos.insert(ic + a);
			}
			ans = max(ans, sum);

			k++;
		}

		c++;
	}

	cout << ans << endl;
	return 0;
}

