namespace prime {
  bool is_prime(ll n) {
    if(n < 2) return false;
    for(ll i = 2; i * i <= n; i++) {
      if(n % i == 0) return false;
    }
    return true;
  }
  vector<ll> divisors(ll n) {
    vector<ll> res;
    for(ll i = 1; i * i <= n; i++) {
      if(n % i == 0) {
        res.push_back(i);
        if(i != n / i) res.push_back(n / i);
      }
    }
    return res;
  }
  map<ll, int> prime_factors(ll n) {
    map<ll, int> res;
    if(n < 2) return res;
    for(ll i = 2; i * i <= n; i++) {
      while(n % i == 0) {
        res[i]++;
        n /= i;
      }
    }
    if(n > 1) res[n] = 1;
    return res;
  }
};

void answer() {
  int n;
  cin >> n;
  vector<ll> s(n);
  rep(i, n) {
    cin >> s[i];
  }
  ll ans = 0;
  REP(i, 2, n-1) {
    ll a = i;
    vector<ll> divisors = prime::divisors(n-1-a);
    for(ll d : divisors) {
      ll b = a - d;
      if(b <= 0 || a <= b) continue;
      if(a % d == 0) {
        ll u = a / d;
        if((u - 1) * d + a < n - 1) continue;
      }
      ll ci = 0, cur = 0;
      while(ci < n-1) {
        ci += a;
        cur += s[ci];
        if(ci >= n-1) {
          if(ci == n-1) chmax(ans, cur);
          break;
        }
        ci -= b;
        cur += s[ci];
      }
    }
  }
  cout << ans << '\n';
}
int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(0);
  answer();
  return 0;
}

