            if (used[n - 1 - k * c]) break;
            used[n - 1 - k * c] = true;

            if (used[k * c]) break;
            used[k * c] = true;

            cur += s[n - 1 - k * c] + s[k * c];
            ans = max(ans, cur);
        }
    }

    cout << ans << "\n";
    return 0;
}

