    ll ans = 0; // A = N-1 のとき, 下限
    // A - B = C の値で全探索
    // C < A, A + C <= N-1 より, C <= N/2 - 1
    for (int i = 1; i <= N/2 -1; ++i) {
        ll dp[(N-1)/i]; // DP[j]はCをj回やってからAでゴール
        dp[0] = 0;
        for (int j = 1; j < (N-1)/i; ++j) {
            if((N-1-i*j == i*j) || (N-1-i*j == i*(j-1))) break;
            dp[j] = dp[j-1] + s[N-1-i*j] + s[i*j];
            ans = max(ans, dp[j]);
        }
    }
    cout << ans;
    return 0;
}

// 解き直し.
// ABC 128解説.
// https://img.atcoder.jp/abc128/editorial.pdf
#include <bits/stdc++.h>
using namespace std;
using LL = long long;
LL S[123321];

int main() {

    // 1. 入力情報取得.
    int N;
    scanf("%d", &N);
    for(int i = 0; i < N; i++) scanf("%lld", S + i);

    // 2. 解説通り.
    // 以下の情報から, 計算するとのこと.
    // 0, (N - 1) - k * C, C, (N - 1) - (k - 1) * C, 2 * C, ... k * C, N - 1.
    // -> f(k + 1, C) = f(k, C) + S[N - 1 - k * C] + S[k * C] (k >= 0)
    LL ans = 0;
    for(int c = 1; c < N; c++){
        LL cur = 0, bef = 0;
        map<LL, int> route; // 経路情報を保存.
        for(int k = 0; k < (N - 1) / c; k++){

            // 2-1. 経路情報チェック.
            // すでに通っていた場合は, 終了.
            int pos1 = N - 1 - k * c;
            int pos2 = k * c;
            route[pos1]++, route[pos2]++;
            if(route[pos1] != 1 || route[pos2] != 1) break;

            // 2-2. cur更新.
            cur = bef + S[pos1] + S[pos2];

            // 2-3. 最終得点更新.
            ans = max(ans, cur);

            // 2-4. bef更新.
            bef = cur;
        }
    }

    // 3. 出力 ～ 後処理.
    printf("%lld\n", ans);
    return 0;

}

