int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    ll n;
    cin >> n;
    vector<ll> s(n);
    for (ll& i : s)
        cin >> i;

    ll ret = 0;
    for (ll c = 1; c < n - 1; c++) {
        vector<bool> used(n, false);
        ll sum = 0;

        if (c >= n - 1 - c)
            continue;

        for (ll k = 1; (n - 1) - (k * c) > 0L; k++) {
            if (n - 1 - c * k > c)
                break;

            ll a0 = (n - 1) - k * c;
            ll a1 = k * c;

            if (used[a0])
                break;
            used[a0] = true;

            if (used[a1])
                break;
            used[a1] = true;

            sum += s[a0] + s[a1];
            ret = max(ret, sum);
        }
    }
    cout << ret << endl;

    return 0;
}

