int FLAG = 0;

int main() {
	clock_t t_BG = clock();

	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%lld", &s[i]);

	long long mx = 0;
	long long iter = 0;

	for (int df = 1; df < n; df++) {
		int bg = df + 1, en = n - 1, a_go = +1;
		if ((n - 1) % df != 0) {
			int rem = (n - 1) % df;
			if (rem < df + 1) rem += df;
			bg = rem;
			en = n - 1;
			a_go = df;
		}

		for (int a = bg; a <= en; a+=a_go) {
			iter++;

			FLAG++;
			long long sum = 0;
			int x = 0;
			int fail = 0;
			int cnt = 0;
			while (1) {
				if (x == n - 1) break;
				if (x < 0 || x > n - 1) {
					fail = 1;
					break;
				}
				if (nnew[x] == FLAG) {
					fail = 1;
					break;
				}
				sum += s[x];
				nnew[x] = FLAG;
				if (cnt % 2 == 0) x += a;
				else x -= a - df;
				cnt++;
			}
			if (!fail)
				mx = max(mx, sum);

			if (iter & 128) {
				if (((double)(clock() - t_BG)) / (CLOCKS_PER_SEC) > 1.8) {
					cout << mx;
					return 0;
				}
			}
		}
	}

	cout << mx;
	return 0;
}

