void solve(long long N, std::vector<long long> s)
{
  lli ans = 0;
  for (lli diff = 1; diff <= N; diff++)
  {
    for (lli k = 0; k * diff <= N - 1; k++)
    {
      vector<bool> used(N);
      lli A = N - 1 - k * diff;
      lli B = A - diff;
      lli cur = 0, turn = 0;
      lli ret = 0;
      while (cur < N - 1)
      {
        cur += turn ? (-B) : A;
        turn ^= 1;
        if (used[cur])
        {
          ret = -1e18;
          cur = N - 1;
          break;
        }
        used[cur] = true;
        ret += s[cur];
      }
      assert(cur == N - 1);
      chmax(ans, ret);
    }
  }
  cout << ans << endl;
}

