void solv() {
	cin >> n;
	ll s[100010];
	for (size_t i = 0; i < n; i++)
	{
		cin >> s[i];
	}

	ll res = 0;
	for (int i = 1; i < ((n - 1) / 2) + 1; i++)
	{
		int rm = (n - 1) - i;
		auto ds = getDivisors(rm);
		if (rm != 1) ds.push_back(rm);
		for (int j= 0; j < ds.size(); j++)
		{
			int vl = (i - ds[j]);
			if (vl % ds[j] == 0) {
				vl = vl / ds[j];
				if (i + (ds[j] * vl) < n - 1) continue;
			}
			ll v = 0;
			ll ps = 0;
			for (int k= i,ps = ds[j]; k < n - 1; k += ds[j],ps += ds[j])
			{
				v += s[k];
				v += s[ps];
			}
			res = max(res, v);
		}

	}

	for (int i = ((n - 1) / 2) + 1; i < n; i++)
	{
		int rm = (n - 1) - i;
		auto ds = getDivisors((n - 1) - i);
		if (ds.size() != rm)ds.push_back(rm);

		for (size_t k = 0; k < ds.size(); k++)
		{
			ll v = 0;
			int po = 0;
			for (size_t j = i; j < n - 1; j += ds[k])
			{
				v += s[j];
				v += s[po + ds[k]];
				po += ds[k];
			}
			res = max(res, v);
		}
	}
	cout << res << endl;
}

