int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    vector<ll> s(n);
    for (ll& i : s)
        cin >> i;

    ll ret = 0;
    for (int c = 1; c <= n - 1; c++) {
        vector<ll> dp(n);
        vector<bool> used(n, false);
        for (int k = 1; (n - 1) - k * c > 0; k++) {
            int a0 = (n - 1) - k * c;
            int a1 = k * c;

            if (used[a0] || used[a1] || a0 == a1)
                dp[k] = -1000000000000000000LL;
            else
                dp[k] = dp[k - 1] + s[a0] + s[a1];

            used[a0] = true;
            used[a1] = true;
        }
        ret = max(ret, *max_element(all(dp)));
    }
    cout << ret << endl;

    return 0;
}

