        L += d;
        R -= d;
        ans = max(ans, sum);
      }

      //割り切れないとき、ＬとＲは全て異なる。ＬがＮ－１を越えない範囲で足し続ける。
    } else {
      while (true) {
        if (L > N - 1) break;
        sum += s[L] + s[R];
        L += d;
        R -= d;
        ans = max(ans, sum);
      }
    }
  }

  cout << ans << endl;
  return 0;
}

