int main() {
    int n;
    while (std::cin >> n) {
        vi s(n); std::cin >> s;
        ll answ(0);
        std::vector<pii> stack;
        auto drop = [&](int x) {
            assert(s[x] != -1);
            stack << pii{x,s[x]};
            s[x] = -1;
        };
        auto revert = [&](){
            for (auto &[x,v] : stack) {
                s[x] = v;
            }
            stack.clear();
        };
        for (int k = 0; k <= n-1; k++) {
            for (int diff = 1; k * diff + (k == 0) * diff < n-1; diff++) {
                int a = n - 1 - k * diff;
                int b = a - diff;
                if (a > 0 && b > 0) {
                    watch(k,diff,a,b);
                    ll curr = s[0];
                    int x = 0;
                    while (true) {
                        watch(x,a,b,curr);
                        int y = x + a;
                        assert(0 <= y && y <= n-1);
                        x = y;
                        if (s[x] == -1) {
                            curr = -INF;
                            break;
                        }
                        curr += s[x];
                        drop(x);
                        if (x == n-1) break;
                        y = x - b;
                        assert(0 <= y && y < n-1);
                        x = y;
                        if (s[x] == -1) {
                            curr = -INF;
                            break;
                        }
                        curr += s[x];
                        drop(x);
                    }
                    revert();
                    std::remax(answ,curr);
                }
            }
        }
        std::cout << answ << std::endl;
    }
    return 0;
}

