	IOS();
	int N;
	cin >> N;
	vector<int>s(N);
	for(int i = 0;i < N;i++){
		cin>>s[i];
	}
	int ans = 0;
	rep(i,1,N/2){
		int l = 0,r = N - 1;
		int cost = 0;
		map<int,int>visit;
		while(0<=r&&l<N&&visit.count(l)==0&&visit.count(r)==0){
			if(l+i>=N-1)break;
			visit[l] = true;
			visit[r] = true;
			cost += s[l] + s[r];
			l += i;
			r -= i;
			chmax(ans,cost);
			if(l==r)break;
		}
	}
	cout<<ans<<endl;
}

