    long s[100000];
    long ans = 0;
    for(int i = 0; i < N; i++) cin >> s[i];
    for(int i = 1; i < (N/2); i++){
        long tmp = 0;
        long sum = 0;
        for(int j = 1; j*i < (N/2); j++){
            sum += s[i*j];
            sum += s[N-i*j-1];
            ans = max(sum, ans);
        }
    }
    for(int i = 2; i < N; i++){
        int B = (N-1)%i;
        int A = B+i;
        long sum = 0;
        if(B <= 0) continue;
        if(B >= A-B) continue;
        for(int j = 1; i*j < N; j++) sum += s[i*j];
        for(int j = 1; i*j+B+i < N; j++) sum += s[i*j+B];
        //cout << i << ' ' << sum << ' ' << A << endl;
        ans = max(sum, ans);
    }
    cout << ans << endl;
}

