int N;
int s[312345];
int d[2123];
bool used[312345];
int main() {
    LL ret = 0;
    scanf("%d",&N);
    for(int i:range(N)){
        scanf("%d",s+i);
    }
    for(int A:range(2,N-1)){
        int ds=0;
        for(int i=1;i*i<=(N-1-A);i++){
            if((N-1-A)%i==0){
                d[ds++]=i;
                d[ds++]=(N-1-A)/i;
            }
        }
        for(int di:range(ds)){
            const int B=A-d[di];
            int p=0;
            LL sum=0;
            while(1){
                p+=A;
                sum+=s[p];
                if(p==N-1){
                    chmax(ret,sum);
                    //cerr << A << " " << B <<  " "  << ret << endl;

                    break;
                }
                used[p]=true;
                p-=B;
                sum+=s[p];
                if(used[p]){
                    break;
                }
            }
            p=0;
            while(1){
                p+=A;
                if(ret==N-1){
                    break;
                }
                used[p]=false;
                p-=B;
                if(!used[p]){
                    break;
                }
            }
        }
    }
    // K=A-B
    /*
        A: A+i*K == N-1 となるK

    */
    printf("%lld\n",ret);
    return 0;
}

