vector<ll> yakusuu_rekkyo(ll n){
    vector<ll> divisors;
    for(ll i = 1; i <= n; i++){
        if(i * i > n)break;
        if(i * i == n){
            divisors.push_back(i);
            break;
        }else if(n % i == 0){
            divisors.push_back(i);
            divisors.push_back(n/i);
        }   
    }
    sort(divisors.begin(), divisors.end());
    return divisors;
}


int main() {
    int n; cin >> n;
    ll a[n] = {};
    rep(i,n) cin >> a[i];
    ll ans = 0;
    srep(i,1,n-1){
        vector<ll> v = yakusuu_rekkyo(n-1-i);
        int m = v.size();
        rep(j,m){
            int c = v[j];
            if(c >= i) break;
            int b = i - c;
            if(b >= i) continue;
            ll tmp = 0;
            int now = 0;
            while(true){
                now += i;
                if(now == n - 1) break;
                tmp += a[now];
                now -= b;
                tmp += a[now];
                if(now - i >= 0 && (now-i)%c == 0){
                    tmp = -1;
                    break;
                }
            }
            ans = max(ans, tmp);
        }
    }

    cout << ans << endl;
    return 0;
}

