int precheck(int a, int b, int n) {
    if (a == n-1) return true;
    if (a <= b) return false;
    // k * (a-b) + a == n-1
    int k = (n - 1 - a) / (a - b);
    if (k * (a-b) + a != n-1) return false;
    if (a % (a-b) != 0) return true;
    int g = a-b;
    if (k * g >= a) return false;
    return -1;
}
int check(int a, int b, int n) {
    vi vis(n);
    int x = 0, step = a, sign = 1, moves(0);
    while (true) {
        if (x >= n || x < 0) return false;
        if (x == n-1) return moves;
        if (vis[x]) return false;
        vis[x] = 1;
        moves++;
        x += sign * step;
        step = a + b - step;
        sign = -sign;
    }
    return moves;
}
bool smart(int a, int b, int n) {
    return precheck(a,b,n) != 0;
}
void research() {
    for (int n = 3; n <= 100; n++) {
        int moves(0);
        for (int a = 1; a < n; a++) {
            for (int b = 1; b < n; b++) {
                assert(!!check(a,b,n) == smart(a,b,n));
                moves += check(a,b,n);
            }
        }
        std::cout << "n = " << n << ": OK, moves=" << moves << std::endl;
    }
    std::exit(0);
}
