ll solve(int A, int B) {
	if((n - 1 - A) / (A - B) >= A / (A - B))
		return 0;

	int x = (n - 1 - A) / (A - B), y = A % (A - B);
	ll res = get(A - B, 0, x);//ps[A - B][0][x];
	res += get(A - B, y, 1 + (n - 1 - (A - B)) / (A - B));//ps[A - B][y][1 + (n - 1 - (A - B)) / (A - B)];
	res -= get(A - B, y, A / (A - B) - 1);//ps[A - B][y][A / (A - B) - 1];
	return res;
}

