		ll sz=(n-1)/c;
		unordered_map<ll,ll> mp;
		ll ans=0;
		for(ll k=1;k<=sz;k++)
		{
			if(mp.count(n-1-k*c)) break;
			mp[n-1-k*c]++;
			if(mp.count(k*c)) break;
			mp[k*c]++;
			ans+=s[k*c]+s[n-1-k*c];
			mx=max(ans,mx);
		 } 
	}
	cout<<mx<<endl;
}

