int gcd(int a, int b) {
  while (b) {
    int c = a;
    a = b;
    b = c % b;
  }
  return a;
}

vector<int64> L[N], R[N];

int64 solve(int64 A, int64 B, int64 n) {
  int64 step = (n - A) / (A - B);
  int64 C = gcd(A, A - B);
  int64 mins = A / C;
  // trace(A, B, n, mins, step);
  if (mins <= step) return -1;
  return L[A - B][step] + R[A - B][step];
}

