int N;

bool ins(set<int>& st, int x){
    if(st.count(x)) return true;
    if(x <= 0) return true;
    if(x >= N-1) return true;
    st.insert(x);
    return false;
}

int main(){

    int64_t S[100000];
    cin >> N;
    for(int i=0; i<N; i++) cin >> S[i];

    int64_t ans = 0;
    for(int d=1; d<N-1; d++){
        int64_t res = 0;
        set<int> st;
        int l = d, r = N-1-d;
        if(l >= r) break;
        while(true){
            if(ins(st, l)) break;
            if(ins(st, r)) break;
            res += S[l] + S[r];
            chmax(ans, res);
            l += d;
            r -= d;
        }
    }
    cout << ans << endl;
    return 0;
}

