class Solution {
public:
    long long solve(vector<long long>& S) {
        int n = S.size();
        int N = n - 1;
        long long res = 0;

        for (int i = 1; i < n - 1; ++i) {
            int l = 0;
            int r = n - 1;
            long long sum = 0;
            if ((n - 1) % i == 0) {
                while (l < r) {
                    sum += S[l];
                    sum += S[r];
                    res = max(res, sum);
                    l += i;
                    r -= i;
                }
            } else {
                while (l + i <= n - 1) {
                    sum += S[l];
                    sum += S[r];
                    res = max(res, sum);
                    l += i;
                    r -= i;
                }
            }
        }
        return res;
    }
};

