bool valid(int A, int B) {
    if (A <= 0 || B <= 0) return false;
    if (A <= B) return false;
    int g = gcd(A, B);
    // A,BをGCDで割ったとき, 差が1じゃないなら大丈夫 (実験したらわかる)
    if (A / g - B / g != 1) return true;
    // mx : 例えば(3,2)のとき, (0,2,4,1,3,5)の順に訪れて, 次はもうどこにも行けない -> ハスが6個以下なら大丈夫
    //      一般化すると, (A,A-1)のとき, ハスが2*A個以下なら大丈夫
    int mx = (A / g + B / g + 1) * g;
    return (N <= mx);
}

