        //N - 1 - k * C > 1 so that A > 1
        for (int k = 0; N - 1 - k * C > 1; k++) {
            if (visited[N - 1 - k * C]) break;
            visited[N - 1 - k * C] = true;

            if (visited[k * C]) break;
            visited[k * C] = true;

            currentProfit += s[k * C];
            currentProfit += s[N - 1 - k * C];

            answer = max(answer, currentProfit);
        }
    }

    printf("%lld\n", answer);
}

