        wa += s[r];
        r -= d;
        dump(l,r,wa);
        chmax(ans,wa);
        wa += s[l];
        l += d;
        if(l>r) break;
      }
    }else{
      ll l,r;
      l = 0;
      r = N-1;
      ll wa = 0;
      while(true){
        wa += s[l];
        wa += s[r];
        chmax(ans,wa);
        l += d;
        r -= d;
