}

//部分削除(未検証)
//ベクトルのi番目(i=0,1,2,...,n-1)の要素を削除し、
//以降の要素を全て前に1ずらして参照返し
//ベクトル長は1小さくなって返る
// i>n-1の時は変化しない
void erase(vector<long long> &v, long long i) {
	long long n = v.size();
	if(i > n - 1) return;
	for(long long j = i; j < n - 1; j++) {
		v.at(j) = v.at(j + 1);
	}
	v.pop_back();
	return;
}

//重複削除(未完成)
//引数ベクトルに同一要素が複数あるとき、先頭を残し他は削除
//参照返し
//ベクトル長も変化する
// O(logn)くらい
void unique(vector<long long> &v) {
	long long n = v.size();
	set<long long> s;
	long long i = 0;
	while(i < n) {
		if(s.count(v.at(i))) {
			erase(v, i);
			n--;
		} else {
			s.insert(v.at(i));
			i++;
		}
	}
	return;
}

