Int N;
vector<Int> s;

void solve(){
	Int ans = 0;
	for(int S = 1;S <= N - 1;S++){
//		int r = (N-1)%S;
		Int sum = 0;
		unordered_set<int> vis;
		int left = 0, right = N - 1;
		for(;;){
			right-=S;
			left+=S;
			if(right<=0 or left>=N-1)break;
			if(vis.find(left)!=vis.end())break;
			vis.insert(left);
			if(vis.find(right)!=vis.end())break;
			vis.insert(right);
			if(left==right)break;
			sum += s[left];
			sum += s[right];
			ans = max(ans,sum);
		}
	}
	cout<<ans<<endl;
}

