ll f(int x,vector<ll> s){
	ll ret = 0;
	int n = s.size();
	ll ma = 0;

	for (int k = 1; k <= (n-1)/x; k++){
		if((n-1)%x==0 &&  n-1-(k-1)*x<=(k-1)*x) break;
		ret += s[n-1-(k-1)*x]+s[(k-1)*x];
		ma = max(ret,ma);
	}
	return ma;
}

int main()
{
	int n;
	cin>>n;
	vector<ll> s(n);
	rep(i,n) cin>>s[i];
	ll ans=0;
	for (int x = 1; x < n; x++){
		ans = max(ans,f(x,s));
	}
	cout<<ans<<endl;
	return 0;
}

