void check(int skip){
	ll sum=0;
	set<int> vst;
	for(int k=0;k*skip<n;++k){
		vst.insert(k*skip);
		if(k==0){
			sum=s[0]+s[n-1];
			res=max(res,sum);
			continue;
		}
		sum+=s[n-1-k*skip]+s[k*skip];
		int a=n-1-k*skip;
		int b=a-skip;
		if(b<1||b>=a) continue;
		if(vst.find(a)!=vst.end()) continue;
		res=max(res,sum);
	}
}

