            int sz = RightSum.size();
            for(int i = k; i < k * sz; i += k){
                LeftSum.emplace_back(LeftSum.back() + s[i]);
            }
            for(int i = 0; i < sz; ++i){
                chmax(ans, LeftSum[i] + RightSum[i]);
            }
        }
