            for(int i = k; i < n / 2; i += k){
                LeftSum.emplace_back(LeftSum.back() + s[i]);
            }
            for(int i = n - k - 1; i >= n / 2; i -= k){
                RightSum.emplace_back(RightSum.back() + s[i]);
            }
            int sz = LeftSum.size();
            for(int i = 0; i < sz; ++i){
                chmax(ans, LeftSum[i] + RightSum[i]);
            }
        }
    }

