bool vis[101010];
int so(int A, int B)
{
  int step = 0, now = 0;
  long long sum = 0;
  //printf("%d %d\n", A, B); fflush(stdout);
  while(true)
  {
    if(step%2==0) now += A;
    else now -= B;
    ++step;
    if(now == N-1) break;
    if(vis[now]) return step;
    vis[now] = true;
    sum += S[now];
  }
  //printf("%d %d %lld\n", A, B, sum); fflush(stdout);
  ans = max(ans, sum);
  return step;
}
void RESET(int A, int B, int stepl)
{
  int now = 0;
  long long sum = 0;
  for(int step=0; step<stepl; ++step)
  {
    if(step%2==0) now += A;
    else now -= B;
    vis[now] = false;
  }
}
void solve(int A, int B)
{
  RESET(A, B, so(A, B));  
}
