      if(NpA%AmB == 0)
      {
        int B1 = A-AmB;
        int B2 = A-NpA/AmB;
        if(1 <= B1 && B1 < A) solve(A, B1);
        if(1 <= B2 && B2 < A) solve(A, B2);
      }
    }
  }
