    vector<ll> dp(n);
    for (int c = 1; c <= n - 1; c++) {
        dp[0] = 0;
        vector<bool> used(n, false);
        for (int k = 1; (n - 1) - k * c > 0; k++) {
            int a0 = (n - 1) - k * c;
            int a1 = k * c;

            if (used[a0] || used[a1] || a0 == a1) {
                dp[k] = -1000000000000000000LL;
                break;
            } else
                dp[k] = dp[k - 1] + s[a0] + s[a1];

            ret = max(ret, dp[k]);

            used[a0] = true;
            used[a1] = true;
        }
    }
    cout << ret << endl;

    return 0;
}

