using namespace std;
typedef long long ll;

ll solve(int n,int C,vector<ll> &s){
    vector<ll> dp{s[0] + s.back()};
    set<int> st{0,n-1};

    for(int i = 1;i*C <= n-1;i ++){
        if(st.find(i*C)!=st.end() || st.find(n-1-i*C)!=st.end() ||
           i*C==n-1-i*C) break;
        else {
            dp.push_back(dp.back() + s[i*C] + s[n-1-i*C]);
            st.insert(i*C);
            st.insert(n-1-i*C);
        }
    }
    sort(dp.begin(),dp.end());
    return dp.back();
}

