int n;
int s[100000];

void take_input()
{
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    cin >> n;
    for (int i = 0; i != n; ++i)
        cin >> s[i];
}

long long simulate(int &A, int &B)
{
    vector<bool> sht(n);
    int x = 0;

    long long ret = 0;

    while (1)
    {
        x += A;
        if (x >= n || sht[x])
            return 0;
        sht[x] = 1;
        if (x == n - 1)
            return ret;
        ret += s[x];

        x -= B;
        if (x < 0 || sht[x])
            return 0;
        sht[x] = 1;
        ret += s[x];
    }
}

void solve()
{
    vector<pair<int, int>> validAB;
    for (int a = 2; a != n; ++a)
    {
        int d = 1;
        while (d < a && d * d < n - a - 1)
        {
            if ((n - a - 1) % d == 0)
            {
                validAB.push_back({a, a - d});
                int recip = (n - a - 1) / d;
                if (recip < a)
                    validAB.push_back({a, a - recip});
            }
            ++d;
        }
        if (d < a && (n - a - 1) == d * d)
            validAB.push_back({a, a - d});
    }

    long long ans = 0;
    for (auto &tmp : validAB)
        ans = max(ans, simulate(tmp.first, tmp.second));

    cout << ans << '\n';
}

int main()
{
    take_input();
    solve();
}

