long long s[100005];

map<int, long long> memo[100005];

int N;

long long dp(int C, int k){
	//printf("%d %d\n", C, k);
	if(k == 0){
		return 0;
	}else if(memo[C].find(k) != memo[C].end()){
		return memo[C][k];
	}else{
		if((N-1)%C == 0 && k*C >= (N+4)/2){
			return memo[C][k] = -1LL << 61;
		}
		return memo[C][k] = dp(C, k-1) + s[(k-1)*C] + s[N-1-(k-1)*C];
	}
}


int main(){
	scanf("%d", &N);

	for(int i = 0; i < N; i ++){
		scanf("%lld", &s[i]);
	}

	long long ans = 0;
	for(int C = 1; C <= N; C ++){
		for(int k = 0; k*C < N; k ++){
			ans = max(ans, dp(C, k));
		}
	}

	printf("%lld", ans);
	return 0;
}

