bool contains_map(const Map &c, const T &v)
{
  return c.find(v) != c.end();
}

/**
 * list up v's divisors( O(sqrt(v)) )
 */
std::vector<uint64_t> divisor(uint64_t v)
{
  std::vector<uint64_t> ret;
  uint64_t fin = std::sqrt(v);

  for(uint64_t div = 1; div<=fin; div++) {
    if(v % div != 0) {
      div++;
      continue;
    }
    ret.push_back(div);
    if(div != v/div) {
      ret.push_back(v/div);
    }
  }
  std::sort(ret.begin(), ret.end());
  return ret;
}

struct SumTarget{
  SumTarget(uint64_t a_b, uint64_t a, uint64_t n):
      delta(a_b), a(a), n(n) {};

  uint64_t delta, a, n;
};

int main()
{
  uint64_t N;
  std::cin >> N;
  std::vector<int64_t> s(N);
  for(uint64_t i=0; i<N; i++) {
    std::cin >> s[i];
  }

  int64_t ret = 0;
  std::vector<SumTarget> sum_targets;
  for(uint64_t A=2; A<N-1; A++) { // skip A==N-1 because ret = 0
    auto divs = divisor(N - 1 - A);

    for(auto div: divs) {
      if(A <= div) continue;

      uint64_t B = A - div;
      // std::cout << "A: " << A
      //           << " N-1-A: " << N-1-A
      //           << " div: " << div
      //           << " B: " << B
      //           << std::endl;

      // calculate possible A and B
      if(A % (A-B) == 0) {
        if(2 * A <= N-1) continue;
      }

      sum_targets.push_back(SumTarget(A-B, A, (N-1-A)/div));
    }
  }

  // search max score

  // sum_caches[diff, A, n] = sum(s[(diff)*i + A], i=0..n)
  std::map<uint64_t, std::map<uint64_t, std::map<uint64_t, int64_t>>> sum_caches;

  auto get_score =
      [&s, &sum_caches](uint64_t delta, uint64_t a, uint64_t n) -> int64_t
      {
        uint64_t n_cache = 0;
        int64_t cache = 0;
        if(contains_map(sum_caches, delta) &&
           contains_map(sum_caches, a)) {
          auto it = sum_caches[delta][a].rbegin();
          if(it->first <= n) {
            n_cache = it->first;
            cache = it->second;
          }
        }

        for(uint64_t i=n_cache; i<=n; i++) {
          cache += s[delta * i + a];
        }

        return cache;
      };

  for(auto &st: sum_targets) {
    uint64_t delta = st.delta;
    uint64_t a = st.a;
    uint64_t n = st.n;

    int64_t cache_a = get_score(delta, a, n);
    sum_caches[delta][a][n] = cache_a;
    int64_t cache_0 = get_score(delta, 0, n);
    sum_caches[delta][0][n] = cache_0;

    /*
    std::cout << "a = " << a
              << " b = " << (a - delta)
              << " delta = " << delta
              << " n = " << n
              << " cache_a = " << cache_a
              << " cache_0 = " << cache_0
              << std::endl;
    */

    // update ret
    ret = std::max(ret, cache_a + cache_0);
  }

  // std::cout << "max_A: " << max_A << " max_B: " << max_B << std::endl;
  std::cout << ret << std::endl;

  return 0;
}

