vector<ll> sumHead[112345];
vector<ll> sumTail[112345];

int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(0);
  cin >> n;
  for(int i = 0; i < n; i++) cin >> s[i];
  ll ans = 0;

  for(int i = 1; i <= n; i++) {
    sumHead[i].push_back(0);
    sumTail[i].push_back(0);
    for(int j = i; j < n; j += i) {
      sumHead[i].push_back(s[j] + sumHead[i].back());
      sumTail[i].push_back(s[n-1-j] + sumTail[i].back());
    }
  }

  for(int A = 2; A <= n - 2; A++) {
    int r = n - 1 - A;
    auto ds = divisor(r);
    for(auto d : ds) {
      int times = r / d + 1;
      if(A <= ll(d) * (times-1) && A % d == 0) continue;
      ll res = sumHead[d][times-1];
      res += sumTail[d][times-1];
      ans = max(ans, res);
      dump(res, d, times, A);
    }
  }
  cout << ans << endl;
  return 0;
}

