class FFrogJump {
public:
    void solve(std::istream& cin, std::ostream& cout) {
        int N;
        cin >> N;
        vector<int> S(N);
        REP(i, N) cin >> S[i];

        int res = -INF;
        FOR(c, 1, N - 1) {
            int sum = 0;
            for (int k = 0; k * c < N - 1; k++) {
                int l = k * c;
                int r = N - 1 - k * c;

                if ((N - 1) % c == 0 && l >= r) break;

                sum += S[l];
                sum += S[r];
                res = max(sum, res);
            }
        }
        cout << res << endl;
    }
};


