ll solve() {
    ll res = 0;
    for (int d = 1; d < n; d++) {
        ll v = 0, v_max = 0;
        int l = 0, r = n-1;
        while (r > d) {
            if (l >= r && r % d == 0) break;
            v += s[l] + s[r];
            v_max = max(v_max, v);
            l += d;
            r -= d;
        }
        res = max(res, v_max);
    }
    return res;
}

