void solve() {
    cin >> N;
    REP(i, N) cin >> S[i];

    REP2(i, 1, 100001) for (ll j = i; j <= 100000; j += i) {
        F[j].push_back(i);
    }

    ll ans = 0;

    for (ll A = 3; A < N - 1; ++A) {
        ll X = N - 1 - A;
        for (auto f: F[X]) {
            ll B = A - f;
            if (B <= 0 || B >= A) continue;
            ll K = X / (A - B);
            if (B % (A - B) == 0) {
                ll g = B / (A - B);
                if (g < K) continue;
            }
            ll tmp = 0;
            for (ll p = 0; p + A < N - 1; p += A - B) {
                tmp += S[p+A];
                tmp += S[p+A-B];
            }
            ans = max(ans, tmp);
        }
    }

    cout << ans << endl;
}

