vector<int> facs[M];
void init() {
    REP(i,1,M-1) {
        int sq = (int)sqrt(i);
        int sq2 = sq*sq;
        REP(j,1,sq) if(i%j==0) {
            facs[i].push_back(j);
            if (sq2==i && j==sq) continue;
            facs[i].push_back(i/j);
        }
    }
}
int main()
{
    init();
    while (~scanf("%d", &n)) {
        REP(i,0,n-1) scanf("%d", &in[i]);
        REP(i,1,n-1) {
            s[i] = 0;
            for (int j=0; j<=n-1; j+=i) s[i] += in[j];
        }

        LL ans = 0;
        REP(A,1,n-2) for(int tmp:facs[n-1-A]) {
            int B = A-tmp;
            if (B<=0) continue;

            // A: t+1 times
            // B: t   times
            // xA = y(A-B)
            int t = (n-1-A)/(A-B);
            int gcd = __gcd(A,A-B);
            int x = (A-B)/gcd;
            int y = A/gcd;
            if (x<=t+1 && y<=t) continue;

            LL sum = s[A] + s[A-B];
            LL lcm = (LL)A*(A-B)/gcd;
            if (lcm<=n-1) sum -= s[lcm];
            ans = max(ans, sum);
        }
        printf("%lld\n", ans);
    }
