VI common_divisor(int x) {
  VI ans;
  int max = (int) sqrt(x);
  REPS(i,1,max+1) {
    if (x % i == 0) {
      ans.pb(i);
      if (i != x/i) {
        ans.pb(x/i);
      }
    }
  }
  return ans;
}

int calc_score(int a,int b,VI s, int n) {
  int cur = 0;
  int score = s[cur];
  char seen[s.size()] = {};

  //printf("A:%lld, B:%lld\n", a,b);
  while (1) {
    cur += a;
    if (cur > n-1 || seen[cur])
      return -1;
    score += s[cur];
    seen[cur] = 1;
    if (cur == n-1)
      return score;

    cur -= b;
    if (cur > n-1 || seen[cur])
      return -1;
    score += s[cur];
    seen[cur] = 1;
    if (cur == n-1)
      return score;
  }
}

