        ll t = 0;
        for (int kd = 0; d < N - 1 - kd; kd += d) {
            used[kd] = d;
            if (used[N - 1 - kd] >= d) {
                break;
            }
            t += s[kd] + s[N - 1 - kd];
            ans = max(ans, t);
        }
    }

    return ans;
}

