  long long ans = 0;
  for(int i = 1; i < N; ++i){
    vector<long long> A(1,0), B(1,0);
    int r = (N-1)%i;
    for(int j = 0; j <= (N-1)/i; ++j){
      A.push_back(S[j*i]);
      B.push_back(S[j*i+r]);
