                        for(int j=i;j<n;j+=l)
                            res+=a[j];
                        for(int j=n-1-i;j<n;j+=l)
                            res+=a[j];
                    }
                    ans=max(ans,res);
                }
                l=r+1;
                if(l>y) break;
                r=y/(y/l);
            }
        }
        else if(s>0)
        {
            int l=1,r=1;
            while(l<=y)
            {
                if(y%l==0&&s%l!=0)
                {
                    ll res=0;
                    if(l<=t)
                        res=bk[l][i]+pre[l][n-1-i];
                    else
