                        for(int j=n-1-i;j<n;j+=l)
                            res+=a[j];
                    }
                    ans=max(ans,res);
                }
                l=r+1;
                if(l>y) break;
                r=y/(y/l);
            }
        }
    }
    printf("%lld\n",ans);
}
