    for(int x = 0; x * C < N; ++x) {
      long A = N-1 - x * C;
      long B = A - C;
      if(A <= 0 || B <= 0 || A < B) break;

      if(used[x * C]) break;
      sum += s[x * C];
      used[x * C] = true;

      if(used[N-1 - x * C]) break;
      sum += s[N-1 - x * C];
      used[N-1 - x * C] = true;

      ans = max(ans, sum);
    }
  }

  cout << ans << endl;
}

