signed main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;
	vector<int> s(n);
	for (auto &t : s) {
		cin >> t;
	}
	if (n > 10000) {
		assert(false);
	}
	int ans = 0;
	auto rlx = [&](int a, int b, int k) {
		int c = a - b;
		if (a % c == 0 && a / c < k) return;
		int cp = 0;
		int cr = 0;
		for (int i = 0;; i++) {
			if (i & 1) {
				cr += s[cp - b];
				cp -= b;
			} else {
				cr += s[cp + a];
				cp += a;
			}
			if (cp == n) break;
		}
		ans = max(ans, cr);
	};
	// rlx(4, 3, 4);
	n--;
	for (int k = 0; k <= n; k++) {
		for (int c = 0; c <= n; c++) {
			int a = n - k * c;
			int b = a - c;
			if (a > 0 && b >= 0 && a > b && a < n) {
				rlx(a, b, k); 
			}
		}
	}
