vl zalgo(string s) {
	ll c = 0;
	vl a(s.size());
	ll si = s.size();
	rep2(i, 1, s.size()) {
		if (i + a[i - c] < c + a[c])
		{
			a[i] = a[i - c];
		}
		else {
			ll j = max(0LL, a[c] - (i - c));
			while (i + j < si && s[j] == s[i + j])
			{
				j++;
			}

			a[i] = j;
			c = i;
		}

	}
	a[0] = s.size();
	return a;
}
string decStrNum(string s) {
	ll si = s.size();
	for (int i = si - 1; i >= 0; i--)
	{
		if (s[i] == '0') {
			s[i] = '9';
			continue;
		}
		s[i] = s[i] - 1;
		break;
	}
	return s;
}

