    ll dist = n - 1;
    for (int A = 1; A <= n - 1; A++)
    {
        ll dementor = dist - A;
        for (int i = 1; i * i <= dementor; i++)
        {
            if (dementor % i == 0)
            {
                check(i, A);
                check(dementor / i, A);
            }
        }
        ll id1 = dementor;
        ll id2 = n - 1 - dementor;
        for (int i = 1; i * i <= id1; i++)
        {
            if (id1 % i == 0)
            {
                summ[i] -= v[id1];
                if (i * i != id1)
                    summ[id1 / i] -= v[id1];
            }
        }
        for (int i = 1; i * i <= id2; i++)
        {
            if (id2 % i == 0)
            {
                summ2[i] -= v[id2];
                if (i * i != id2)
                    summ[id2 / i] -= v[id2];
            }
        }
    }
