bool safe(int N, int C, int k) {
  // A + Ck = N - 1
  int A = N - 1 - C * k;
  if (A <= 0) return false;
  // C = A - B
  int B = A - C;
  if (B <= 0 || B >= A) return false;
  if (A % C != 0) return true;
  return (A / C) > k;
}

