void res(int A, int B)
{
    if (n != A - B + A && A == 2 * B) return;
    long long r = 0;
    int x = 0;
    while (x != n)
    {
        x += A;
        r += a[x];
        if (x == n) break;
        x -= B;
        r += a[x];
    }
    ans = max(ans, r);
}

