        for (int d = 1; d * d <= x; d++)
        {
            if (x % d == 0)
            {
                int amb = d;
                int A = amb + B;

                if (A > B)
                    res(A, B);

                amb = x / d;
                A = amb + B;

                if (A > B)
                    res(A, B);
            }
        }
    }
    cout << ans;
}

