template<class Type>
Type solve(Type res = Type()){
    ll N; cin >> N;
    vector<ll> s(N); for(auto& in:s) cin >> in;

    for(int C = 1; C < N;C++){
        map<ll,int> mp;
        ll dp = 0;
        for(int k = 1; k*C < N-1; k++){
            ll p1 = N-1-k*C;
            ll p2 = k*C;
            if(mp[p1]) break;
            if(mp[p2]) break;
            mp[p1]++;
            mp[p2]++;

            dp += s[N-1-k*C] + s[k*C];
            res = max(res,dp);
        }
    }
    return res;
}
