void _main()
{
    ll n; llin(n);
    V<ll> slist; llina(slist, n);

    ll ans = 0LL;

    srep (freq, 1, n) {
        ll sum = 0LL;
        srep (cnt, 1, n) {
            ll left = freq * cnt;
            ll right = (n - 1LL) - freq * cnt;
            if (right < 0LL) break;
            if (left >= right && ((right % freq) == 0LL)) break;
            sum += slist[left];
            sum += slist[right];
            ans = max(ans, sum);
        }
    }

    cout << ans << endl;
}

