	for(int i=0;i<n;i++) cin>>v[i];
	for(int i=0;i<n;i++) calc[i] = v[i] + v[n-i-1];

	long long ans = 0;
	for(int i=1;i<n;i++){
		long long tmp = 0;
		if(i == n-i-1) continue;
		tmp = calc[i];
		for(int j=i+i;j<n;j+=i){
