		cin >> S[i];
	}

	ll ans = 0;

	for (int C = 1; C < N - 1; C++) {
		//C=A-B 
		dp[0] = 0;
		set<int> used;
		for (int i = 1;; i++) {

			if (i * C >= N - 1)break;
			if (N - 1 - i * C <= 0)break;
			if (N - i - i * C <= C)break;
			if (2 * C * i == N - 1)continue;

			if (used.find(i * C) != used.end() || used.find(N - 1 - i * C) != used.end())break;

			dp[i] = dp[i - 1] + S[i * C] + S[N - 1 - i * C];
			used.insert(i * C), used.insert(N - 1 - i * C);

			ans = max(ans, dp[i]);
		}

	}
	cout << ans << endl;
	return 0;
}

