void rgen(map<i64, i64>& p, map<i64, i64>::iterator it, i64 v, vector<i64>& q, i64 a) {
    if (v >= a) {
        return;
    }

    if (it == p.end()) {
        i64 t = a / v;
        i64 k = (n - 1 - a) / v;

        if (a % v == 0 && t <= k) {
            return;
        }
        q.push_back(v);
        return;
    }


    auto nit = it;
    nit++;

    for (i64 i = 0; i <= it->second; i++) {
        rgen(p, nit, v, q, a);
        v *= it->first;
    }
}

void gen(i64 v, vector<i64>& q, i64 a) {
    map<i64, i64> p;

    for (auto t : primes) {
        if (v == 1) {
            break;
        }

        if (t > v) {
            break;
        }

        while (v % t == 0) {
            v /= t;
            p[t]++;
        }
    }

    rgen(p, p.begin(), 1, q, a);
}

