	repn(i, N - 1) {
		ll bound = N - 1;
		if ((N - 1) % i == 0) { bound = (N - 1) / 2; }

		ll w = -INF;

		ll v = 0;

		for (ll j = 0; j < bound; j += i) {
			v += a[j];
			w = max(w, v);
		}


		ans = max(ans, w);

	}

	cout << ans;


	system("PAUSE");



}

