            auto bad = [&](int p) {
                su += V[p];
                if (was[p] == ab)return true;
                else return false;
            };
            l += ab;
            r -= ab;
            if (bad(l))break;
            if (bad(r))break;
            if(l >= r)break;
            int a = r;
            int b = a - minl;
            if(!(a > b))break;
            if(!(san(0,a,N) && san(0,b,N)))break;
            chma(ma, su);
        }
    }
    return ma;
}

