using namespace std;

const int MAXN = 1e5 + 5;

int a[MAXN], n;
vector<int> pref[MAXN], revPref[MAXN], posAns[MAXN];
int ans = 0;

int main(){
	scanf("%d", &n);
	for(int i = 0; i < n; ++i){
		scanf("%d", &a[i]);
	}

	// Precompute sum for all d
	for(int d = 1; d < n; ++d){
		for(int i = 0; i < n; i += d){
			int tmp = (pref[d].empty()) ? 0:pref[d][pref[d].size()-1];
			tmp += a[i];
			pref[d].push_back(tmp);
		}
	}
	for(int d = 1; d < n; ++d){
		for(int i = n-1; i >= 0; i -= d){
			int tmp = (revPref[d].empty()) ? 0:revPref[d][revPref[d].size()-1];
			tmp += a[i];
			revPref[d].push_back(tmp);
		}
	}
	//printf("Precomp complete\n");

	// Get possible d for all N-1-A
	for(int d = 1; d <= n; ++d){
		for(int i = 0; i*d < n; ++i){
			posAns[n-1-(i*d)].push_back(d);
		}
	}
	//printf("D complete\n");

	// For all valid A and d, check the answer
	for(int A = 2; n-1-A >= 0; ++A){
		int m = n-1-A;
		// Get num of seq 0, d, 2d, ...
		for(int d : posAns[m]){
			int tmp = m/d;
			if(A%d == 0 && tmp*d >= n-1-(tmp*d)) continue;
			int tmpAns = revPref[d][tmp];
			if(tmp)
				tmpAns += pref[d][tmp];
			//printf("(%d, %d) = %d\n", A, d, tmpAns);
			ans = max(ans, tmpAns);
		}
	}
	printf("%d\n", ans);
}

