      if (x * C >= N)
      {
        break;
      }
      int A = (N - 1) - x * C;
      int B = A - C;
      if (B <= 0)
      {
        break;
      }
      int forward = N - 1 - x * C;
      if (S.find(forward) != S.end())
      {
        break;
      }
      score += s[forward];
      S.insert(forward);
      int back = x * C;
      if (S.find(back) != S.end())
      {
        break;
      }
      score += s[back];
      S.insert(back);
      ans = max(ans, score);
      x++;
    }
  }
  cout << ans << endl;
}

