    rep(i, 0, N) cin >> S[i];
    ll ans = 0;
    rep(i, 0, N){
        if(i >= N - 1 - i) break;
        Score.push_back(S[i] + S[N-1-i]);
    }
    int k = Score.size();
    vector<ll> memo(k + 1, 0);
    rep(i, 1, k + 1){
        auto div = divisor(i);
        for(auto d: div){
            memo[d] += Score[i];
            chmax(ans, memo[d]);
        }
    }
    cout << ans << endl;
    return 0;
}

