		for (ll A = 2; A < N; A++) {
			if (((k + 1) * A - N + 1) % k != 0) continue;
			ll B = ((k + 1) * A - N + 1) / k;
			if (B <= 0 || A <= B || done[A][B]) continue;
			done[A][B] = true;

			int idx = 0;
			int count = 0;
			ll score = 0;
			vb visited(N, false);
			while (idx != N - 1) {
				if (count % 2 == 0)
					idx += A;
				else
					idx -= B;

				if (visited[idx]) {
					score = numeric_limits<ll>::min();
					goto GETSCORE;
				}
				else {
					score += s[idx];
					visited[idx] = true;
				}
				count++;
			}

		GETSCORE:
			ans = max(ans, score);
		}
	}

	say(ans);


	return 0;
}

