    long long point = 0;
    for (int k = 0; k < N; k++) {
      int s1 = N - 1 - k * c;
      int s2 = k * c;
      if (s1 <= s2) break;
      if (passed[s1] || passed[s2]) break;

      point += s[s1] + s[s2];
      ans = max(ans, point);

      passed[s1] = passed[s2] = true;
    }
  }

  cout << ans << endl;

  return 0;
}

