void check(int skip){
	ll sum=0;
	set<int> vst;
	for(int i=0,j=0;i<=n-1;i+=skip,++j){
		vst.insert(i);
		sum+=s[i];
		int a=n-1-i;
		int b=a-skip;
		if(a<2||b<1||b>=a) continue;
		bool ok=true;
		ll tmp=sum;
		int k;
		for(k=a;k<=n-1;k+=skip)
			if(vst.find(k)!=vst.end()){
				ok=false;
				break;
			}else tmp+=s[k];
		if(ok) res=max(res,tmp);
	}
}

