void check(int last,int skip){
	int a=n-1-last;
	int b=a-skip;
	if(b<1||b>=a) return;
	ll sum=0;
	int i=0;
	vector<bool> vst(n,false);
	while(true){
		i+=a;
		if(i>=n||vst[i]) return;
		sum+=s[i];
