    for (int c = 1; c <= n - 1; ++c) {
        ll sum = 0;

        set<int> visited;
        for (int k = 0; k * c < n - 1; ++k) {
            if (k * c == n - 1 - k * c) break;
            if (visited.count(k * c) or visited.count(n - 1 - k * c))
