vector<int> divisors(int N) {
  vector<int> res;
  for (int k = 1; k * k <= N; k++) {
    if (N % k == 0) {
      res.push_back(k);
      if (k != N / k) {
        res.push_back(N / k);
      }
    }
  }
  return res;
}

int used[100010];

ll simulate(const vector<ll>& S, int A, int B) {
  static int id = 0;
  ++id;
  int N = S.size();
  ll sum = 0;
  used[0] = id;
  for (int p = 0;;) {
    if (used[p + A] == id) return -1;
    p += A;
    used[p] = id;
    sum += S[p];
    if (p == N - 1) return sum;
    if (used[p - B] == id) return -1;
    p -= B;
    used[p] = id;
    sum += S[p];
    if (p == N - 1) return sum;
  }
  return sum;
}

