int main() {
    int n;
    in(n);

    auto s = vin<i64>(n);

    pair<i64, pair<int, int>> ans(0, make_pair(n - 1, 0));

    for (int a = 2; a < n; a++) {
        for (int b = 1; b < a; b++) {
            vector<int> v(n, 0);
            v[0] = 1;

            i64 score = 0;
            int pos = 0;

            while (true) {
                pos = pos + a;

                if (0 <= pos && pos < n && !v[pos]) {
                    score += s[pos];
                    v[pos] = 1;

                    if (pos == n - 1) {
                        break;
                    }
                } else {
                    score = -1;
                    break;
                }

                pos = pos - b;

                if (0 <= pos && pos < n && !v[pos]) {
                    score += s[pos];
                    v[pos] = 1;
                } else {
                    score = -1;
                    break;
                }
            }

            ans = max(ans, make_pair(score, make_pair(a, b)));
        }
    }

    out(ans.first);
}

