vector<int> divisor(int n){
    vector<int> v;
    int i = 1;
    while (i*i < n){
        if (n % i == 0){
            v.push_back(i);
            v.push_back(n/i);
        }
        ++i;
    }
    if(i*i == n) v.push_back(i);
    // sort(v.begin(), v.end());
    return v;
}

