            if (visited[pos] == i || visited[N-1-pos] == i|| pos == N-1-pos) {
                break;
            }
            visited[pos] = visited[N-1-pos] = i;
            sum += s[pos] + s[N-1-pos];
            chmax(res, sum);
            pos += i;
        }

    }
    cout << res << endl;
}

