	int ans=0;
	for(int D=1;D<N;D++){
		if((N-1)%D==0){
			int s=0;
			for(int j=1;2*j<(N-1)/D;j++){
				s+=S[j*D]+S[N-1-j*D];
				chmax(ans,s);
			}
		}
		else{
			int s=0;
			for(int j=1;j*D<N;j++){
				s+=S[j*D]+S[N-1-j*D];
