int lot[100000];
long long dp[100000];

int main(void) {
	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%d", &lot[i]);

	long long max = dp[0] = 0;
	for (long long c = 1; c < n-1; c++) {
		for (long long k = 1; k*c < n-1; k++) {
			if ((n-1)%c == 0 && (n-1) <= 2*k*c + c) break;
			dp[k] = dp[k-1] + lot[n-1 - k*c] + lot[k*c];
			if (max < dp[k]) max = dp[k];
		}
	}
	printf("%lld\n", max);
