#include<stdio.h>
#include<stdlib.h>
#include<stdint.h>
#include<inttypes.h>

typedef int32_t i32;
typedef int64_t i64;

#define MAX(a,b) ((a) > (b) ? (a) : (b))

void run (void) {
  i32 n = 1000;
  scanf ("%" SCNi32, &n);
  i32 *s = (i32 *) calloc (n, sizeof (i32));
  for (i32 i = 0; i <n; ++i) {
    scanf ("%" SCNi32, s + i);
  }
  i64 max = 0;
  for (i32 d = 1; d < n - d; ++d) {
    i64 sum = 0;
    for (i32 k = 1; n - 1 - k * d > 0; ++k) {
      sum += s[k * d] + s[n - 1 - k * d];
      i32 b = n - 1 - k * d;
      if (b % d == 0 && b / d < k) break;
      max = MAX (max, sum);
    }
  }
  printf ("%" PRIi64 "\n", max);
}

int main (void) {
  run();
  return 0;
}

