import java.io.PrintWriter

val pw = PrintWriter(System.out)
fun main(args: Array<String>) {
    func()
    pw.flush()
}
fun println(value: Any) { pw.println(value) }

fun func() {
    val N = nextInt()
    val S = listOfInt()
    var ans = 0L
    for (C in 1 until N) {
        var score = 0L
        var X = 0
        while (C * X < N) {
            val n = C * X
            val a = (N - 1) - n
          //val b = a - C
            if (n >= a && (N - 1) % C == 0) break
            if (a <= C) break
            score += S[n] + S[a]
            ans = Math.max(ans, score)
            X++
        }
    }
    println(ans)
}

