class FastScanner {
    private final InputStream in = System.in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;
    private boolean hasNextByte(){
        if(ptr<buflen) return true;
        else{
            ptr = 0;
            try{
                buflen = in.read(buffer);
            }
            catch(IOException e){
                e.printStackTrace();
            }
            if(buflen<=0) return false;
        }
    return true;
    }
    private int readByte() { if (hasNextByte()) return buffer[ptr++]; else return -1;}
    private static boolean isPrintableChar(int c) { return 33 <= c && c <= 126;}
    public boolean hasNext() { while(hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++; return hasNextByte();}
    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while(isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }
    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) throw new NumberFormatException();
        while(true){
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            }
            else if(b == -1 || !isPrintableChar(b)) return minus ? -n : n;
            else throw new NumberFormatException();
            b = readByte();
        }
    }
    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) throw new NumberFormatException();
        return (int) nl;
    }
    public double nextDouble() { return Double.parseDouble(next());}
    public void close(){
        try{in.close();}
        catch(IOException e){e.printStackTrace();}
    }
}

import java.io.*;
import java.util.*;

public class Main implements Runnable {
	public static void main (String[] args) {new Thread(null, new Main(), "_cf", 1 << 28).start();}

	public void run() {
		FastScanner fs = new FastScanner();
		PrintWriter out = new PrintWriter(System.out);
		System.err.println("");

//		it();

		int N = fs.nextInt();
		int[] a = fs.nextIntArray(N);
		long res = a[0]+a[N-1];
		int[] used = new int[N];
		for(int diff = 1; diff <= N; diff++) {
			long last = a[0]+a[N-1];
			for(int k = 1; k <= N; k++) {
				if((long)k*diff > N-1) break;
				int val = k*diff;
				int A = N-1 - val;
				if(A == val) break;
				if(A <= 0  || A >= N-1) break;
				if(used[A] == diff || used[N-1-A] == diff) break;
//				System.out.println(diff + " " + k);
				used[A] = diff;
				used[N-1-A] = diff;
				long add = a[A];
				add += a[N-1-A];
				last += add;
				res = Math.max(res, last);
			}
		}
		out.println(res);


		out.close();
	}

	void it() {

		int use = 6;
		for(int N = use; N <= use; N++) {
			System.out.println("For N = " + N);
			for(int C = 1; C <= N; C++) {
				for(int k = 0; k <= N; k++) {
					int val = k*C;
					if(val > N-1) break;
					int A = (N-1)-val;
					if(A <= 0 /*|| A == val*/) break;

					boolean[] reach = new boolean[N];
					int mask = 0;
					int cur = 0;
					boolean bad = false;
					while(true) {
						reach[cur] = true;
						mask |= 1<<cur;
						int next = cur+A;
						if(next > N-1 || reach[next]) {
							bad = true;
							break;
						}
						reach[next] = true;
						mask |= 1 << next;
						if(next == N-1) break;
						next = cur+C;
						if(next < 0 || reach[next]) {
							bad = true;
							break;
						}
						cur = next;
						mask |= 1 <<next;
					}
					if(!bad) {
						System.out.println(C + " " + k + " " + (A) + " " + Integer.toBinaryString(mask));
					}
				}
				System.out.println();
			}
		}

	}

	class FastScanner {
		public int BS = 1<<16;
		public char NC = (char)0;
		byte[] buf = new byte[BS];
		int bId = 0, size = 0;
		char c = NC;
		double num = 1;
		BufferedInputStream in;

		public FastScanner() {
			in = new BufferedInputStream(System.in, BS);
		}

		public FastScanner(String s) {
			try {
				in = new BufferedInputStream(new FileInputStream(new File(s)), BS);
			}
			catch (Exception e) {
				in = new BufferedInputStream(System.in, BS);
			}
		}

		public char nextChar(){
			while(bId==size) {
				try {
					size = in.read(buf);
				}catch(Exception e) {
					return NC;
				}                
				if(size==-1)return NC;
				bId=0;
			}
			return (char)buf[bId++];
		}

		public int nextInt() {
			return (int)nextLong();
		}

		public long nextLong() {
			num=1;
			boolean neg = false;
			if(c==NC)c=nextChar();
			for(;(c<'0' || c>'9'); c = nextChar()) {
				if(c=='-')neg=true;
			}
			long res = 0;
			for(; c>='0' && c <='9'; c=nextChar()) {
				res = (res<<3)+(res<<1)+c-'0';
				num*=10;
			}
			return neg?-res:res;
		}

		public double nextDouble() {
			double cur = nextLong();
			return c!='.' ? cur:cur+nextLong()/num;
		}

		public String next() {
			StringBuilder res = new StringBuilder();
			while(c<=32)c=nextChar();
			while(c>32) {
				res.append(c);
				c=nextChar();
			}
			return res.toString();
		}

		public String nextLine() {
			StringBuilder res = new StringBuilder();
			while(c<=32)c=nextChar();
			while(c!='\n') {
				res.append(c);
				c=nextChar();
			}
			return res.toString();
		}

		public boolean hasNext() {
			if(c>32)return true;
			while(true) {
				c=nextChar();
				if(c==NC)return false;
				else if(c>32)return true;
			}
		}

		public int[] nextIntArray(int n) {
			int[] res = new int[n];
			for(int i = 0; i < n; i++) res[i] = nextInt();
			return res;
		}

	}

}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] s = new int[N];
        for (int i = 0; i < s.length; ++i) {
            s[i] = sc.nextInt();
        }

        System.out.println(solve(s));

        sc.close();
    }

    static long solve(int[] s) {
        long result = 0;
        for (int delta = 1; delta * 2 < s.length - 1; ++delta) {
            Set<Integer> backIndices = new HashSet<>();
            int backIndex = delta;
            long backSum = 0;
            while (backIndex < s.length - 1 - delta) {
                backSum += s[backIndex];
                backIndices.add(backIndex);
                backIndex += delta;
            }

            Set<Integer> frontIndices = new HashSet<>();
            int frontIndex = s.length - 1 - delta;
            long frontSum = 0;
            int duplicateCount = 0;
            for (int i = 0; i < backIndices.size(); ++i) {
                if (backIndices.contains(frontIndex)) {
                    ++duplicateCount;
                }

                frontSum += s[frontIndex];
                frontIndices.add(frontIndex);
                frontIndex -= delta;
            }

            int lastBackIndex = backIndex - delta;
            int firstFrontIndex = frontIndex + delta;
            while (!frontIndices.isEmpty()) {
                if (duplicateCount == 0) {
                    result = Math.max(result, frontSum + backSum);
                }

                if (frontIndices.contains(lastBackIndex)) {
                    --duplicateCount;
                }
                backSum -= s[lastBackIndex];
                backIndices.remove(lastBackIndex);
                lastBackIndex -= delta;

                if (backIndices.contains(firstFrontIndex)) {
                    --duplicateCount;
                }
                frontSum -= s[firstFrontIndex];
                frontIndices.remove(firstFrontIndex);
                firstFrontIndex += delta;
            }
        }

        return result;
    }
}

