    static int solve() {
        boolean[] check = new boolean[N];
        // NのときAの最大値はN-2, そのときB=1とするとN-3まで
        int ans = 0;
        for (int d = 1; d < N-3; d++) {
            Arrays.fill(check, false);
            int sum = 0;
            int u = 0;
            int v = N-1;
            check[u] = true;
            check[v] = true;

            while(true) {
                u += d;
                v -= d;
                // debug(d, u, v);

                if( u >= N-1 || v <= 0) break;
                if( check[u] || check[v] ) break;
                if( u == v ) break;

                sum += S[u];
                sum += S[v];
                check[u] = true;
                check[v] = true;
            }
            ans = Math.max(ans, sum);
        }
        return ans;
    }

