            while (true) {
                int ni1 = k * C, ni2 = N - 1 - k * C;
                if (!(0 <= ni1 && ni1 < N && 0 <= ni2 && ni2 < N)) {
                    break;
                }
                if (ni1 == ni2 || used[ni1] || used[ni2]) {
                    break;
                }
                used[ni1] = used[ni2] = true;
                cur += s[ni1] + s[ni2];
                res = Math.max(res, cur);
                k++;
            }
        }
