    public void solve() {
        int N = in.nextInt();
        long[] s = in.nextLongArray(N);

        long res = 0;
        int[] used = new int[N];
        for (int C = 1; C <= N - 2; C++) {
            int k = 1;
            long cur = 0;
            used[0] = C;
            while (true) {
                int ni1 = k * C, ni2 = N - 1 - k * C;
                if (!(0 <= ni1 && ni1 < N && 0 <= ni2 && ni2 < N)) {
                    break;
                }
                if (ni1 == ni2 || used[ni1] == C || used[ni2] == C) {
                    break;
                }
                used[ni1] = used[ni2] = C;
                cur += s[ni1];
                cur += s[ni2];
                res = Math.max(res, cur);
                k++;
            }
        }
        System.out.println(res);
    }

