    static class FFrogJump {
        public void solve(int testNumber, MyInput in, PrintWriter out) {
            int n = in.nextInt();
            int[] s = in.nextIntArray(n);

            long ans = Long.MIN_VALUE;
            int[] id = new int[n];
            for (int i = 1; i < n; i++) {
                long v = 0;
                for (int l = 0, r = n - 1; l != r && r >= 0; l += i, r -= i) {
                    if (id[l] == i || id[r] == i) break;
                    v += s[l];
                    v += s[r];
                    id[l] = i;
                    id[r] = i;
                    ans = Math.max(v, ans);
                }
            }
