		for(int diff = 1; diff <= N; diff++) {
			long last = a[0]+a[N-1];
			for(int k = 1; k <= N; k++) {
				if((long)k*diff > N-1) break;
				int val = k*diff;
				int A = N-1 - val;
				if(A == val) break;
				if(A <= 0 || A == diff || A >= N-1) break;
				if(used[A] == diff || used[N-1-A] == diff) continue;
				System.out.println(diff + " " + k);
				used[A] = diff;
				used[N-1-A] = diff;
				long add = a[A];
				add += a[N-1-A];
				last += add;
				res = Math.max(res, last);
			}
		}
		out.println(res);


		out.close();
