                arr[i] = in.nextLong();
            //long res = solveSimple(n, arr);
            long res = solveMe2(n, arr);
            out.println(res);
        }

        private long solveMe2(int n, long[] s) {
            long max = 0;
            long[] dp = new long[n + 1];
            for (int d = 1; d < n; d++) {
                int maxn = n - d;
                if ((n - 1) % d == 0) maxn = n / 2;
                for (int k = 1; k * d < maxn; k++) {
                    dp[k] = dp[k - 1] + s[k * d] + s[n - 1 - k * d];
                    max = Math.max(max, dp[k]);
                }
            }
            return max;
        }

    }
