import java.util.ArrayList;
import java.util.Scanner;

public class Main {

    private static ArrayList<Integer> leaf_list;
    private static ArrayList<Integer> test_leaf_list;

    //検証用リストの初期化
    public static void init(int leaf_num) {
        test_leaf_list = new ArrayList(leaf_num);
        for (int score : leaf_list) {
            test_leaf_list.add(score);
        }
    }

    public static void main(String[] args) {
        //標準入力からデータを読み込み
        Scanner sc = new Scanner(System.in);
        int leaf_num = sc.nextInt();
        leaf_list = new ArrayList(leaf_num);
        for (int i = 0; i < leaf_num; i++) {
            leaf_list.add(sc.nextInt());
        }

        int max_score = Integer.MIN_VALUE, score, pos, cnt;
        for (int a = 1; a < leaf_num; a++) {
            for (int b = 1; b < a; b++) {
                init(leaf_num);
                score = 0;
                pos = 0;
                cnt = 0;
                while (true) {
                    //進むと戻るを交互に実施
                    if (cnt % 2 == 0) {
                        pos = pos + a;
                    } else {
                        pos = pos - b;
                    }

                    //現在の場所が範囲外の場合は終了
                    if ((0 > pos) || (pos >= leaf_num)) {
                        break;
                    //蓮がなければ終了
                    } else if (test_leaf_list.get(pos) == Integer.MIN_VALUE) {
                        score -= 10 ^ 100;
                        if (max_score < score) {
                            max_score = score;
                        }
                        break;
                    //終点に到着すれば終了
                    } else if (pos == leaf_num - 1) {
                        if (max_score < score) {
                            max_score = score;
                        }
                        break;
                    //それ以外は得点を加算
                    } else {
                        score += test_leaf_list.get(pos);
                    }

                    test_leaf_list.set(pos, Integer.MIN_VALUE);
                    cnt++;
                }
            }
        }
        System.out.println(max_score);
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;

public class Main {

    static int N;
    static int[] S;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        S = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static long solve() {
        boolean[] check = new boolean[N];
        // NのときAの最大値はN-2, そのときB=1とするとN-3まで
        long ans = 0;
        for (int d = 1; d <= N-3; d++) {
            debug();
            debug("d", d);
            Arrays.fill(check, false);
            long sum = 0;
            long max = 0;
            int u = 0;
            int v = N-1;
            check[u] = true;
            check[v] = true;

            while(true) {
                u += d;
                v -= d;
                // debug("u", u, "v", v);

                // この辺怪しいな…
                if( u >= N-1 || v <= 0) break;
                if( check[u] || check[v] ) break;
                if( u == v ) break;

                sum += S[u];
                sum += S[v];
                max = Math.max(max, sum);
                check[u] = true;
                check[v] = true;
            }
            // debug("d", d, "max", max);
            ans = Math.max(ans, max);
        }
        return ans;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++) a[i] = nextLong();
            return a;
        }
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static void writeSingleLine(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < as.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(as[i]);
        }
        pw.println();
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg == null) j.add("null");
            else if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }

    static void printSingleLine(int[] array) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int i = 0; i < array.length; i++) {
            if (i != 0) pw.print(" ");
            pw.print(array[i]);
        }
        pw.println();
        pw.flush();
    }

    static int lowerBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] < value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int upperBound(int[] array, int value) {
        int lo = 0, hi = array.length, mid;
        while (lo < hi) {
            mid = (hi + lo) / 2;
            if (array[mid] <= value) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

