    InputStream is;

    int __t__ = 1;
    int __f__ = 0;
    int __FILE_DEBUG_FLAG__ = __f__;
    String __DEBUG_FILE_NAME__ = "src/C1";

    FastScanner in;
    PrintWriter out;

    public void solve() {
        int N = in.nextInt();
        long[] s = in.nextLongArray(N);

        long res = 0;
        int[] used = new int[N];
        for (int C = 1; C <= N - 2; C++) {
            long k = 1;
            long cur = 0;
            used[0] = C;
            while (true) {
                long ni1 = k * C, ni2 = N - 1 - k * C;
                if (!(0 <= ni1 && ni1 < N && 0 <= ni2 && ni2 < N)) {
                    break;
                }
                int i1 = (int) ni1, i2 = (int) ni2;
                if (ni1 == ni2 || used[i1] == C || used[i2] == C) {
                    break;
                }
                used[i1] = C;
                used[i2] = C;
                cur += s[i1];
                cur += s[i2];
                res = Math.max(res, cur);
                k++;
            }
        }
        System.out.println(res);
    }

    /* MOD_CALCULATION */
    int MOD = 1_000_000_007;
    long ADD(long a, long b) {
        return (a + b) % MOD;
    }

    long SUB(long a, long b) {
        return (a - b + MOD) % MOD;
    }

    long MULT(long a, long b) {
        return (a * b) % MOD;
    }

    long POW(long a, long x) {
        long res = 1;
        for ( ; x > 0; x >>= 1) {
            if (x % 2 == 1) res = MULT(res, a);
            a = MULT(a, a);
        }

        return res;
    }

    long DIV(long a, long b) {
        return MULT(a, POW(b, MOD - 2));
    }
    /* end */


