import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);

    int N = scanner.nextInt();
    int[] s = new int[N];
    for (int i = 0; i < N; i++) s[i] = scanner.nextInt();
    long[] t = new long[N];
    for (int i = 0; i < N; i++) t[i] = (long) s[i] + s[N - i - 1];

    long[] u = new long[N];
    long[] v = new long[N];
    for (int i = 1; i < N; i++) {
      for (int j = 1; (long) j * j <= i; j++) {
        if (i % j == 0) {
          if (i >= N / 2 && (N - 1) % j == 0) continue;
          u[j] += t[i];
          v[j] = Math.max(v[j], u[j]);
          if (i / j != j) {
            u[i / j] += t[i];
            v[i / j] = Math.max(v[i / j], u[i / j]);
          }
        }
      }
    }
    long max = 0;
    for (int i = 0; i < N; i++) max = Math.max(max, v[i]);
    System.out.println(max);
  }
}

import java.util.*;

public class Main {
	public static void main (String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] arr = new int[n];
		for (int i = 0; i < n; i++) {
			arr[i] = sc.nextInt();
		}
		long max = arr[0];
		for (int a = n - 2; a >= (n + 1) / 2; a--) {
			for (int b = a - 1; b >= 1; b--) {
				int[] test = (int[])(arr.clone());
				int idx = 0;
				boolean flag = true;
				long point = 0;
				while (idx != n - 1) {
					point += test[idx];
					test[idx] = Integer.MIN_VALUE;
					idx += a;
					if (idx >= n || test[idx] == Integer.MIN_VALUE) {
						flag = false;
						break;
					}
					if (idx == n - 1) {
						break;
					}
					point += test[idx];
					test[idx] = Integer.MIN_VALUE;
					idx -= b;
					if (idx < 0 || test[idx] == Integer.MIN_VALUE) {
						flag = false;
						break;
					}
				}
				if (!flag) {
					break;
				}
				max = Math.max(point, max);
			}
		}
		System.out.println(max);
	}
}

