		for(int N = use; N <= use; N++) {
			System.out.println("For N = " + N);
			for(int C = 1; C <= N; C++) {
				for(int k = 0; k <= N; k++) {
					int val = k*C;
					if(val > N-1) break;
					int A = (N-1)-val;
					if(A <= 0 /*|| A == val*/) break;

					boolean[] reach = new boolean[N];
					int mask = 0;
					int cur = 0;
					boolean bad = false;
					while(true) {
						reach[cur] = true;
						mask |= 1<<cur;
						int next = cur+A;
						if(next > N-1 || reach[next]) {
							bad = true;
							break;
						}
						reach[next] = true;
						mask |= 1 << next;
						if(next == N-1) break;
						next = cur+C;
						if(next < 0 || reach[next]) {
							bad = true;
							break;
						}
						cur = next;
						mask |= 1 <<next;
					}
					if(!bad) {
						System.out.println(C + " " + k + " " + (A) + " " + Integer.toBinaryString(mask));
					}
				}
