		Solve();
		Out.Flush();
	}
	void Solve()
	{
		var N = F;
		var s = GL;
		var max = 0L;
		for (var d = 1; d < N; d++)
		{
			var used = new HashSet<int> { 0, N - 1 };
			var sum = 0L;
			int l = 0, r = N - 1;
			while (true)
			{
				l += d;
				r -= d;
				if (used.Contains(l) || used.Contains(r) || l == r || l >= N || r < 0) break;
				used.Add(l);
				used.Add(r);
				sum += s[l] + s[r];
				max = Max(max, sum);
			}
		}
		WriteLine(max);
	}
