		string[]str = Console.ReadLine().Split();
		for(var i=0;i<N;i++){
			S[i] = int.Parse(str[i]);
		}
		long ans = 0;
		for(var i=1;i<=N;i++){
			long a = 0;
			for(var k=1;k<=N/i;k++){
              	if(k*i>=N-1 || (N-1-k*i<=k*i && (N-1)%i == 0)){
                  break;
                }
				a += S[N-1-k*i];
				a += S[k*i];
				ans = Math.Max(ans,a);
			}
		}
		Console.WriteLine(ans);
	}
}

