    class F
    {
        static void Main(string[] args)
        {
            Method(args);
        }

        static void Method(string[] args)
        {
            int n = ReadInt();
            long[] ss = ReadLongs();
            long res = 0;
            for(int i = 1; i < n; i++)
            {
                long temp = 0;
                long sum = 0;
                var useSet = new HashSet<long>();
                for(int j = 1; i * j < n-1; j++)
                {
                    long other = n - i * j - 1;
                    useSet.Add(i * j);
                    if (useSet.Contains(other)) break;

                    sum += ss[i * j] + ss[other];
                    temp = Max(temp, sum);
                }
                res = Max(res, temp);
            }
            WriteLine(res);
        }

