public class Prog
{
    private const int INF = 1000000007;
    private struct Pair { public int x, y; public Pair(int x, int y) { this.x = x; this.y = y; } }
    public static void Solve()
    {
        int N = NextInt();
        List<long> has = Enumerable.Range(0, N).Select(v => NextLong()).ToList();
        // X = B - A
        //双方からXで進むと考える
        long ans = 0;
        for (int x = 1; x < N; x++)
        {
            long sum = 0;
            int L = 0, R = N - 1;
            if ((N - 1) % x == 0)
            {
                //落ちるので L < R を保つ
                while (L < R)
                {
                    sum += has[L] + has[R];
                    ans = Math.Max(sum, ans);
                    L += x;
                    R -= x;
                }
            }
            else
            {
                //交わらないので L < R じゃなくてok
                int A = (N - 1) - L;
                while (x < A)
                {
                    sum += has[L] + has[R];
                    ans = Math.Max(sum, ans);
                    L += x;
                    R -= x;
                    A = (N - 1) - L;
                }
            }
        }
        Console.WriteLine(ans);
    }

    public static void Main()
    {
        var sw = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
