class Program
{
    private static void chmin<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == 1 ? val : num;
    private static void chmax<T>(ref T num, T val) where T : IComparable<T>
        => num = num.CompareTo(val) == -1 ? val : num;
    private static void swap<T>(ref T v1, ref T v2)
    { var t = v2; v2 = v1; v1 = t; }
    static void Main(string[] args)
    {
        var pr = new Program();
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        pr.Solve();
        Console.Out.Flush();
    }
    void Solve()
    {
        var num = Input.num;
        var ss = Input.arL;
        var res = 0L;
        for(var i = 1; i < num; i++)
        {
            var calc = 0L;
            if ((num - 1) % i != 0)
                for (int k = 0, q = num - 1; k < num-1 && q > i; k += i, q -= i)
                    calc += ss[k] + ss[q];
            else
                for (int k = 0, q = num - 1; k < q; k += i, q -= i)
                    calc += ss[k] + ss[q];
            chmax(ref res, calc);
        }
        WriteLine(res);
    }
}

