using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.InteropServices;
using System.Text;

namespace AtCoder
{
    class Program
    {

        static void Main(string[] args)
        {
            new Program().Solve();
        }

        public void Solve()
        {
            var sc = new Scanner();

            // 0
            // A
            // A-B
            // A-B+A
            // ...
            // N - 1 - A
            // N - 1

            // 偶数ターンは(A-B)*(i/2)にいる
            // 奇数ターンは(A-B)*(i/2) + A
            // はみ出るとすっごいマイナスなのではみ出ることは考えない
            // なのでゴールは奇数ターン
            // A - B = Cとすると
            // 移動する蓮は C * jと(N-1) - C*k
            // Aは(N - 1) - C * kの最小値
            // Cを固定して使う蓮を累積和で足していく
            int N = sc.NextInt();
            int[] s = sc.IntArray();

            long ans = 0;
            // Cの範囲は1 ~ N - 1

            for (int c = 1; c < N ; c++)
            {
                long left = 0;
                long right = 0;
                for (int t = 0; t * c < N; t++)
                {
                    int lpos = c * t;
                    int rpos = N - 1 - c * t;
                    if(rpos % c == 0 && rpos <= lpos)
                        break;

                    left += s[t * c];
                    right += s[N - 1 - t * c];
                    ans = Math.Max(ans, left + right);
                }
            }
            Console.WriteLine(ans);
        }
    }
}

