            // 0
            // A
            // A-B
            // A-B+A
            // ...
            // N - 1 - A
            // N - 1

            // 偶数ターンは(A-B)*(i/2)にいる
            // 奇数ターンは(A-B)*(i/2) + A
            // はみ出るとすっごいマイナスなのではみ出ることは考えない
            // なのでゴールは奇数ターン かつ A > B
            // A - B = Cとすると
            // 移動する蓮は C * jと(N-1) - C*k
            // Cを固定して使う蓮を累積和で足していく
            // 計算量はO(NlogN)
            int N = sc.NextInt();
            long[] s = sc.LongArray();

            long ans = long.MinValue;
            // Cの範囲は1 ~ N - 1

            for (int c = 1; c < N - 1; c++)
            {
                long left = 0;
                long right = 0;
                for (int t = 0; t < N; t += c)
                {
                    int lpos = t;
                    int rpos = N - 1 - t;

                    if (rpos <= lpos)
                        break;

                    // Console.WriteLine($"{c} {lpos} {rpos}");
