class Program
{
    static int n;
    static long[] s;

    static void Main()
    {
        n = int.Parse(Console.ReadLine());
        s = Console.ReadLine().Split().Select(long.Parse).ToArray();
        long ans = 0;
        for (int c = 1; c < n - 1; c++) // 各c=a-bについて
        {
            long[] sum1 = new long[(n - 1) / c + 1]; // 0,c,2c...の累積和
            for (int i = 1; i < sum1.Length; i++)
                sum1[i] = sum1[i - 1] + s[i * c];
            long[] sum2 = new long[(n - 1) / c + 1]; // n-1,n-1-c,n-1-2c,...の累積和
            for (int i = 1; i < sum2.Length; i++)
                sum2[i] = sum2[i - 1] + s[n - 1 - i * c];
            long[] scores = new long[(n - 1) / c + 1];
            for (int i = 1; i < scores.Length; i++)
                if ((n - 1) % c != 0 || n - 1 > (long)2 * i * c)
                    scores[i] = sum1[i] + sum2[i];
            ans = Max(ans, scores.Max());
        }
        Console.WriteLine(ans);
    }
}

