        static void Solve()
        {
            int N = Cin.Int;
            var s = Cin.ReadSplitLong;
            var sumf = new List<long>[N];
            var sumb = new List<long>[N];
            for(var i = 0; i < N; i++)
            {
                sumf[i] = new List<long>() { 0 };
                sumb[i] = new List<long>() { 0 };
                if (i == 0) continue;
                for(var j = i; j <= N - 1; j += i)
                {
                    sumf[i].Add(sumf[i].Last() + s[j]);
                }
                for (var j = N - 1 - i; j >= 0; j -= i)
                {
                    sumb[i].Add(sumb[i].Last() + s[j]);
                }
            }
            long ans = 0;
            for(var a = 1; a < N - 1; a++)
            {
                int x = N - a - 1;
                if (x <= 0) continue;
                var bl = new HashSet<int>();
                for(var i = 1; i <= Sqrt(x); i++)
                {
                    if (x % i == 0)
                    {
                        if (a - i > 0) bl.Add(a - i);
                        if (a - (x / i) > 0) bl.Add(a - (x / i));
                    }
                }
                foreach(var b in bl)
                {
                    int k = x / (a - b);
                    if (k <= 0) continue;
                    if (a % (a - b) == 0 && k >= a / (a - b)) continue;

                    ans = Max(ans, sumf[(a - b)][k] + sumb[a - b][k]);
                }
            }
            OutL(ans);

        }
