var scanner *bufio.Scanner

func nextInt() int {
	scanner.Scan()

	var i, _ = strconv.Atoi(scanner.Text())

	return i
}

func nextString() string {
	scanner.Scan()

	return scanner.Text()
}

func initScanner() {
	scanner = bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
}

type Node struct {
	Point int
}

func NewNode(point int) Node {
	return Node{
		Point: point,
	}
}

func maxInt(a, b int) int {
	return int(math.Max(float64(a), float64(b)))
}
func minInt(a, b int) int {
	return int(math.Min(float64(a), float64(b)))
}

func main() {
	initScanner()

	var n = nextInt()

	var nodes = make([]Node, n)
	for i := 0; i < n; i++ {
		nodes[i] = NewNode(nextInt())
	}

	var max = -1

	for c := 1; c < n-1; c++ {
		var sum = 0
		var touched = make([]bool, len(nodes))

		var x = 0

		for {
			var a = (n - 1) - minInt(c*x, n-1)
			var b = a - minInt(c, a)

			if a == 0 || b == 0 {
				break
			}

			// 最後のジャンプ
			if touched[(n - 1 - a)] {
				break
			}

			sum += nodes[n-1-a].Point
			touched[n-1-a] = true

			// 最初のジャンプ
			if touched[a] {
				break
			}
			sum += nodes[a].Point
			touched[a] = true

			max = maxInt(max, sum)
			x++
		}

	}

	fmt.Println(max)
}

