		panic(nil)
	}
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func max(x, y int) int {
	if x > y {
		return x
	}
	return y
}

func answer(reader io.Reader, writer io.Writer) {
	sc = bufio.NewScanner(reader)
	buf := make([]byte, BufferSize)
	sc.Buffer(buf, 1e+6)
	sc.Split(bufio.ScanWords)
	n := nextInt()
	s := make([]int, n)
	for i := range s {
		s[i] = nextInt()
	}

	// 16
	// (4,1) 4,3,7,6,10,9,13,12,16 (4,12)
	// (7,4) 7,3,10,6,13,9,16 (7, 9)
	// (10,7) 10,3,13,6,16 (10,6)
	// (13,10) 13,3,16 (13,3)
	// (16,13) 16
	//
	// n-1 = (a-b)*x+a -> n-a-1 = (a-b) * x
	// a!=2(a-b) -> a != 2b
	// a!=3(a-b) -> 2a != 3b

	// 0 -4 0 -99 31 14 -15 -39 43 18 0`
	// (6,4) 6,2,8,4,10
	// -15+0+43+31+0
	// (10,8) 10
	// (8,6) 8,2,10 (8,2)
	// (6,4) 6,2,8,4,10 (6,4)
	// (4,2) 4,2,6,4 (xx)
	ans := 0
	for c := 1; c < n; c++ {
		a := n - 1
		sc := s[a]
		i := 1
		a -= c
		for a > c {
			if i*c >= n-1-i*c {
				break
			}
			sc += s[n-1-c*i] + s[c*i]
			ans = max(ans, sc)
			i++
			a -= c
		}
	}
	_, _ = fmt.Fprintf(writer, "%d", ans)
}

func main() {
	answer(os.Stdin, os.Stdout)
}

