	writer := bufio.NewWriter(os.Stdout)

	var n int
	fmt.Sscan(getNextLine(scanner), &n)
	ss := getIntList(scanner)

	max := 0
	for c := 1; c < n; c++ {
		score := 0
		for x := 0; x*c < n-1; x++ {
			a := n - 1 - x*c
			if a <= c {
				break
			}
			if (n-1)%c == 0 && n-1 <= 2*x*c {
				break
			}
			score += ss[x*c] + ss[n-1-x*c]
			if max < score {
				max = score
			}

		}
	}

