func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	ss := make([]int64, n)
	for i := 0; i < n; i++ {
		ss[i] = getNextInt64(scanner)
	}

	var ans int64
	for a := 3; a < n; a++ {
		dd := div(n - 1 - a)
		for _, d := range dd {
			b := a - d
			if b < 2 || (n-1-a)/b > 1 {
				continue
			}
			i := 0
			c := 0
			s := int64(0)
			for i < n-1 {
				s += ss[i]
				c++
				if c%2 == 1 {
					i += a
					continue
				}
				i -= b
			}
			if ans < s {
				ans = s
			}
		}
	}
	fmt.Fprintln(writer, ans)
}

func div(x int) []int {
	dd := make([]int, 0)
	for i := 1; i*i <= x; i++ {
		if x%i == 0 {
			dd = append(dd, i)
			if i*i < x {
				dd = append(dd, x/i)
			}
		}
	}
	return dd
}

