void main() {
  long N;
  scanln(N);
  long[] as = readln.split.to!(long[]);
  long ans = 0;
  foreach(d; 1..N) {
    long s = 0;
    foreach(p; 0..(N-1).floor(d)+1) {
      s += as[p*d] + as[N-1-p*d];
      long a = N-1-p*d;
      long b = a-d;
      if (a<=0 || a>=N) continue;
      if (b<=0 || b>=a) continue;
      if (a%d == 0 && a/d <= p) continue;
      if (p*d + a != N-1) continue;
      ans.ch!max(s);
    }
  }
  ans.writeln;
}

