let read = iterator: string {.closure.} =
  while true:
    for s in stdin.readLine.split:
      yield s

let
  n = read().parseInt
  si = stdin.readLine.split.map parseInt
var memo = initTable[string, (int, HashSet[int])]()
let default_set = toSet([n-1])

proc fc(k, c: int): (int, HashSet[int]) =
  if k == 0:
    return (si[n-1], default_set)

  let key = "$1_$2" % [repr(k), repr(c)]
  if memo.contains(key):
    return memo[key]

  var
    (res_before, set_fc) = fc(k-1, c)
    res = low(int)
  let (x1, x2) = (n-1-k*c, k*c)

  # echo "---"
  # echo c, ", ", k
  # echo x1, ", ", x2
  # echo res_before
  # echo set_fc
  # echo "---"

  if res_before == low(int) or set_fc.contains(x1) or set_fc.contains(x2) or x1 == x2:
    discard
  else:
    res = res_before + si[x1] + si[x2]
    set_fc.incl(x1)
    set_fc.incl(x2)

  memo[key] = (res, set_fc)
  return memo[key]

var ans = si[n-1]
for c in 1..<n-1:
  var k = 1
  while c * k < n-1 and (1 + 2 * k) * c < 2 * (n - 1):
    let (score, _) = fc(k, c)
    # echo c, ", ", k, ", ", score
    if score == low(int):
      break
    if score > ans:
      ans = score
    k += 1

