import numpy as np


def main(N, scores):
    M = N - 1
    def max_score(d):
        even_steps = [scores[i] for i in range(0, M - d, d)]
        odd_steps = [scores[i] for i in range(M, d, -d)]
        scores_at_even_steps = np.cumsum(even_steps)
        scores_at_odd_steps = np.cumsum(odd_steps)
        cum_scores = scores_at_even_steps + scores_at_odd_steps

        if M % d > 0:
            return max(cum_scores)
        else:
            k = M // d + 1
            return max(cum_scores[: k // 2])

    corner_case = scores[0] + scores[M]
    otherwise = max(max_score(d) for d in range(1, M))
    return max(corner_case, otherwise)


