def get_factors(X):
    res = defaultdict(int)
    for i in range(bisect(P, sqrt(X))):
        while True:
            d, m = divmod(X, P[i])
            if m:
                break
            res[P[i]] += 1
            X = d
    if X != 1:
        res[X] += 1
    return res


