fn main() {
    input! {
        n: usize, s: [i64; n]
    };

    let mut best = s[n-1];
    let mut visited = vec![0; n];
    for d in 1..n {
        let mut total = s[n-1];
        let mut low = 0;
        let mut high = n-1;
        while true {
            if high <= d*2 || low+d*2 >= n-1 {
                break;
            }
            high -= d;
            low += d;
            if high == low {
                break;
            }
            if visited[high] != d {
                visited[high] = d;
            } else {
                break;
            }
            if visited[low] != d {
                visited[low] = d;
            } else {
                break;
            }

            total += s[high];
            total += s[low];
            best = max(best, total);
            // debug!(d, high, low, best);
        }
    }

    println!("{}", best);
}

