use std::cmp::{max, min};

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let s: Vec<i64> = sc.vec(n);
    let mut head_sum = vec![vec![0]; n + 1];
    let mut tail_sum = vec![vec![0]; n + 1];
    for k in 1..(n + 1) {
        let mut cur = k;
        for i in 0.. {
            if cur >= n {
                break;
            }
            let next_sum = head_sum[k][i] + s[cur];
            head_sum[k].push(next_sum);

            let next_sum = tail_sum[k][i] + s[n - 1 - cur];
            tail_sum[k].push(next_sum);

            cur += k;
        }
    }

    let mut ans = 0;
    for k in 1..(n + 1) {
        for count in 1..head_sum[k].len() {
            let sum = head_sum[k][count] + tail_sum[k][count];
            let head_max = k * count;
            let a = n - 1 - head_max;
            if a <= k {
                continue;
            }
            if head_max >= a && a % k == 0 {
                continue;
            }

            ans = max(ans, sum);
        }
    }

    println!("{}", ans);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

