fn run() {
    input! {
        n: usize,
        s: [isize; n],
    }

    let mut answer = isize::min_value();
    for d in 1..n {
        let start = (n - 1) % d;
        let start = if start == 0 { d } else { start };

        let mut a = Vec::new();
        let mut b = Vec::new();
        let l = (n - 1) / d;
        for k in 0..l {
            a.push(s[k * d]);
            b.push(s[start + k * d]);
        }

        let mut a_sum = a.iter().sum::<isize>();
        let mut b_sum = a.iter().sum::<isize>();

        for k in 0..l - 1 {
            let a_last = (l - 2 - k) * d;
            let b_first = start + (k + 1) * d;
            a_sum -= a[l - 1 - k];
            b_sum -= b[k];
            if a_last < b_first {
                answer.set_max(a_sum + b_sum);
            }
        }
    }

    println!("{}", answer);
}

//{{{ template
fn main() {
    let _ = ::std::thread::Builder::new()
        .name("run".to_string())
        .stack_size(256 * 1024 * 1024)
        .spawn(run)
        .unwrap()
        .join()
        .unwrap();
}

pub trait SetMinMax {
    fn set_min(&mut self, v: Self) -> bool;
    fn set_max(&mut self, v: Self) -> bool;
}

impl<T> SetMinMax for T
where
    T: PartialOrd,
{
    fn set_min(&mut self, v: T) -> bool {
        *self > v && {
            *self = v;
            true
        }
    }
    fn set_max(&mut self, v: T) -> bool {
        *self < v && {
            *self = v;
            true
        }
    }
}

#[derive(PartialEq, Eq, Debug, Copy, Clone, Default, Hash)]
pub struct Reverse<T>(pub T);

impl<T: PartialOrd> PartialOrd for Reverse<T> {
    #[inline]
    fn partial_cmp(&self, other: &Reverse<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }

    #[inline]
    fn lt(&self, other: &Self) -> bool {
        other.0 < self.0
    }
    #[inline]
    fn le(&self, other: &Self) -> bool {
        other.0 <= self.0
    }
    #[inline]
    fn ge(&self, other: &Self) -> bool {
        other.0 >= self.0
    }
    #[inline]
    fn gt(&self, other: &Self) -> bool {
        other.0 > self.0
    }
}

impl<T: Ord> Ord for Reverse<T> {
    #[inline]
    fn cmp(&self, other: &Reverse<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

