fn run() {
    input! {
        n: usize,
        s: [isize; n],
    }

    let mut answer = isize::min_value();
    for d in 1..n {
        let start = (n - 1) % d;
        let start = if start == 0 { d } else { start };

        let mut a = Vec::new();
        let mut b = Vec::new();
        for k in 0..n {
            a.push(s[k * d]);
            b.push(s[start + k * d]);
            if start + k * d == n - 1 {
                break;
            }
        }
        let l = a.len();
        //dbg!(d);
        //dbg!(&a);
        //dbg!(&b);
        //dbg!(start);

        let mut a_sum = a.iter().sum::<isize>();
        let mut b_sum = b.iter().sum::<isize>();

        for k in 0..l - 1 {
            let a_last = (l - 2 - k) * d;
            let b_first = start + (k + 1) * d;
            a_sum -= a[l - 1 - k];
            b_sum -= b[k];
            //dbg!(d);
            //dbg!(k);
            //dbg!(a_sum + b_sum);
            if a_last < b_first || start % d != 0 {
                answer.set_max(a_sum + b_sum);
            }
        }
    }

    println!("{}", answer);
}

