use std::cmp::max;

fn main() {
    input!{
        n: usize,
        v: [isize; n]
    }
    let mut ans: isize = 0;
    for c in 1..n - 1 {
        let mut s: isize = 0;
        for i in 1..(n - 1) / c + 1 {
            s += v[i * c] + v[n - 1 - i * c];
            if (n - 1) % c == 0 && (n - 1) / c <= 2 * i {
