use std::cmp::max;
fn main() {
    input! { n, s: [i64; n] };
    let mut ans = 0;
    for d in 1..n - 1 {
        let mut used = vec![false; n];
        used[0] = true;
        used[n - 1] = true;
        let mut acc = 0;
        let mut i = 1;
        while i * d < n
            && !used[i * d]
            && !used[n - 1 - i * d]
            && i * d != n - 1 - i * d
            && d < n - 1 - i * d
        {
            used[i * d] = true;
            used[n - 1 - i * d] = true;
            acc += s[i * d] + s[n - 1 - i * d];
            ans = max(ans, acc);
            i += 1;
        }
    }
    println!("{}", ans);
}

