use std::cmp;

fn calc_prefsum_list(ss: &[i64]) -> Vec<Vec<i64>> {
    (0..ss.len()).map(|step| {
        if step == 0 {
            return Vec::new()
        }
        ss.iter().step_by_(step).lscan(0, |&a, &b| a + b).collect()
    }).collect()
}

fn main() {
    read!(n = u64);
    read!(ss = Vec<i64>);
    let rev_ss: Vec<i64> = ss.iter().rev().cloned().collect();

    let prefsum_list = calc_prefsum_list(&ss);
    let rev_prefsum_list = calc_prefsum_list(&rev_ss);

    let mut ans = 0;
    for k in 1..n {
        for c in 1..(n-1).ceil_div(k) {
            if let Some(a) = (n-1).checked_sub(k*c) {
                if a <= c {
                    continue;
                }
                if a % c == 0 {
                    let t = a/c;
                    if (t-1)*c + a < n-1 {
                        continue;
                    }
                }
                let k = k as usize;
                let step = c as usize;
                let sum = prefsum_list[step][k+1] + rev_prefsum_list[step][k+1];
                dbg!((k, a, c, sum));
                ans = cmp::max(ans, sum);
            }
        }
    }
    println!("{}", ans);
}

use std::io::*;
use std::str::FromStr;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n = read::<usize>();
    let mut seq = vec![0; n];
    for i in 0..n {
        seq[i] = read::<i64>();
    }
    let ans = solve(&seq);
    println!("{}", ans);
}

fn solve(seq: &Vec<i64>) -> i64 {
    let n = seq.len();
    let mut ret = 0;
    let mut visit = vec![false; n];
    for skip in 1..n {
        let mut sum = 0;
        let mut max_k = 0;
        for k in 1..n {
            let a = n - 1 - skip * k;
            if a < skip {
                break;
            }
            let mut l = skip * k;
            if skip * k >= n - 1 {
                break;
            }
            let mut r = n - 1 - skip * k;
            if visit[l] || visit[r] || l == r {
                break;
            }
            visit[l] = true;
            visit[r] = true;
            sum += seq[l] + seq[r];
            ret = std::cmp::max(ret, sum);
            max_k = k;
        }
        for k in 1..(max_k + 1) {
            let mut l = skip * k;
            let mut r = n - 1 - skip * k;
            visit[l] = false;
            visit[r] = false;
        }
    }
    return ret;
}

