        let mut s = 0;
        let mut set: HashSet<usize> = HashSet::new();
        for i in 1..(n - 1) / c + 1 {
            s += v[i * c] + v[n - 1 - i * c];
            if !set.insert(i * c) || !set.insert(n - 1 - i * c) {
                break;
            }
