fn main() {
    let N = read!(usize);
    let S = read![[i64]];

    // A=N-1, B=1 で必ずスコア 0 を達成できる
    let mut max_sum = 0;

    // C = A - B
    for C in 1..N {
        // 踏んだ蓮のスコアの総和
        let mut sum = 0;

        // 踏んだ蓮の集合
        let mut done = BTreeSet::new();

        // ジャンプ回数 2x + 1 の経路を探索 (O(log N))
        let mut x = 0;
        loop {
            let A = N - 1 - min(N - 1, x * C);
            let B = A - min(A, C);
            if A == 0 || B == 0 {
                break;
            }

            // 最後のジャンプの1回前の戻りジャンプ
            let u = N - 1 - A;
            if !done.insert(u) {
                // 同じ蓮を踏んだ
                break;
            }
            sum += S[u];

            // 最初のジャンプ
            let v = A;
            if !done.insert(v) {
                break;
            }
            sum += S[v];

            max_sum = max(max_sum, sum);

            // 今のループで踏んだ蓮は次のループでも踏むので sum や done はそのままでよい
            x += 1;
        }
    }

    println!("{}", max_sum)
}

