use std::io::prelude::*;

fn input<T: std::str::FromStr>() -> T {
    let stdin = std::io::stdin();
    let token: String = stdin
        .lock()
        .bytes()
        .map(|c| c.unwrap() as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().unwrap()
}

fn main() {
    let n: usize = input();
    let s: Vec<i64> = (0..n).map(|_| input()).collect();

    let mut ans = 0;
    for i in 1..n {
        let mut now = 0;
        let mut v = vec![false; n];
        for j in 1..n {
            let (k1, k2) = (i * j, n - 1 - i * j);
            if k1 == k2 || k2 <= i || v[k1] || v[k2] {
                break;
            }
            v[k1] = true;
            v[k2] = true;
            now += s[k1] + s[k2];
            ans = std::cmp::max(ans, now);
        }
    }

    println!("{}", ans);
}

