    for skip in 1..n {
        let mut sum = 0;
        let mut l = 0;
        let mut r = n - 1;
        while l < r {
            sum += seq[l] + seq[r];
            ret = std::cmp::max(ret, sum);
            l += skip;
            if r < skip {
                break;
            }
            r -= skip;
        }
    }
    return ret;
}

