pub fn divisor(n: usize) -> Vec<usize> {
    let mut divisors = vec![];
    for i in 1..((n as f32).sqrt() as usize + 1) {
        if n % i == 0 {
            divisors.push(i);
            if i != i / n {
                divisors.push(i / n);
            }
        }
    }
    divisors
}
